-- Supplementary guide texts (zhCN) for the shared Polestar_Guides pack
-- (professions, reputations, mounts, pets, dungeons, ...).
-- Only entries the official Polestar_zhCN lacks; official text always wins.

local _, E = ...
if not (GetLocale and GetLocale() == "zhCN") then return end

local G = E.guides

-- Format:
-- G["forever/shared/<guide-id>"] = {
--   ["English original"] = "中文",
-- }

G["forever/class/hunter/rhokdelar"] = {
	["Before the demons"] = "恶魔之前",
	["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, stands in southern {zone:1447}, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around {area:2245}, the cave south of {area:2255} in {zone:1452}, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver."] = "哈斯塔特的箭袋需要{item:18704}。{npc:6109}是一名团队副本世界首领，站在{zone:1447}南部，每两到四天才刷新一次，几乎每次必掉。{area:2245}（{zone:1452}中{area:2255}南边的洞穴）内及其周边的精英钴蓝龙类约每200次击杀掉落一次；那里的法力之爪掉落略多。如果不需要箭袋，可以跳过本篇攻略的其余内容。",
	["Hunter"] = "猎人",
	["Learn {spell:19878} and get demon-slaying potions"] = "学会{spell:19878}，并备好屠魔药水",
	["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and talking to Vartrus once more then gave {item:18715}, at no extra cost."] = "在 Forever 未确认。在原版中，背包里带着{item:18724}时使用{item:18707}即可制作伦鲁迪洛尔，之后再与瓦特鲁斯交谈一次就能拿到{item:18715}，无需额外花费。",
	["Onyxia is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. She drops one {item:18705} in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first."] = "奥妮克希亚是{area:2159}的40人团队副本首领，那里是{zone:1445}南部{area:511}中的一处洞穴；她每周刷新一次。她约每五次击杀中有两次掉落一个{item:18705}，没有任务也能拾取，所以每次只有一名猎人能拿到：先商量好归属。",
	["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring an {item:9224} ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "这四个恶魔是60级精英，伪装成友善的旅行者；与其中一个交谈并表明你知道它是什么，它就会变回恶魔形态。每一场都必须单挑：不带宠物（解散它），战斗开始后不能有其他玩家的治疗、增益或攻击，否则恶魔会骂你懦夫并消失，要等3小时才会回来（它死亡后同样如此）。开怪前加的增益和使用药水没问题，朋友也可以在场边帮你清理游荡的怪物或敌对玩家，只要他们不碰恶魔、也不碰你。带上一个{item:9224}（{skill:171}制作或在拍卖行购买）、用于长时间风筝的强效法力药水，以及一把附有屠魔的武器（如果可以）。训练师处学到的{spell:19878}能在小地图上显示伪装的恶魔。组队时把拾取方式设为自由拾取，这样你才能拾取头颅。",
	["Vartrus, Stoma and {npc:14526} are petrified trees on a small island in a ring-shaped lake in {area:1767}, north {zone:1448}. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to {area:1998}; Horde: fly to {area:1997}. Vartrus gives {quest:7636}, Stoma A Proper String, Hastat the quiver; each can be handed in on its own."] = "瓦特鲁斯、斯托玛和{npc:14526}是{area:1767}环状湖泊小岛上的石化树木，位于{zone:1448}北部。只有携带石叶的人爬上岛上的小丘、走到东侧边缘，它们的灵魂才会出现。联盟：飞往{area:1998}；部落：飞往{area:1997}。瓦特鲁斯给{quest:7636}，斯托玛给“合适的弓弦”，哈斯塔特给箭袋任务；三者可以分别交付。",
	["{area:2717} is a 40-player raid inside {area:254}. When {npc:12018} yields, the {object:179703} appears; it holds the {item:18703} about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest."] = "{area:2717}是{area:254}里的40人团队副本。{npc:12018}倒下后会出现{object:179703}；其中约有一半几率装有{item:18703}，每次一个，所以可能需要好几周的团队副本。右键点击石叶即可开始任务。",
	["{npc:14527}, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use {spell:19878}. Talk to her and she becomes {npc:14533}, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her {spell:421} hits hard, so drain her mana with {spell:3034} (a 15-second cooldown on Forever) and keep her busy; her {spell:23205} cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free."] = "{npc:14527}是一名带着狼的巨魔，沿一条长路线行走，从安戈洛西部的湖泊出发，最远可到环形山南部；用{spell:19878}找她。与她交谈后她会变成{npc:14533}，她的狼普雷舍斯也会变成魔犬。四者中最难的一个：先冰冻陷阱定住普雷舍斯，把西蒙妮拉到远处开怪；或者把普雷舍斯风筝走、先杀掉它，让西蒙妮脱战复位后再单独对付她。她的{spell:421}伤害很高，所以用{spell:3034}抽干她的法力（Forever 中15秒冷却）并不断干扰她；她的{spell:23205}会降低你的远程攻强，所以改用近战解决她。在普雷舍斯挣脱之前拾取她的头颅。",
	["{npc:14529}, a human, wanders the western {zone:1428} south of {area:254}. Talk to him and he becomes {npc:14534}, the easiest of the four. Keep {spell:3043} on him the whole fight: while it lasts he barely hurts you. When he goes into {spell:23257}, remove it with {spell:19801} and never stand in melee while it is up; between frenzies you can fight him in melee with {spell:2974} and {spell:2973}. He cannot leave the {zone:1428}, so kite him around the trees if needed."] = "{npc:14529}是人类，在{area:254}南边的{zone:1428}西部游荡。与他交谈后他会变成{npc:14534}，是四者中最容易的。整场战斗都保持{spell:3043}：只要它还在，他几乎伤不到你。当他进入{spell:23257}状态时，用{spell:19801}驱散，状态存在期间绝不要站在近战范围；狂暴间歇可以用{spell:2974}和{spell:2973}与他近战。他无法离开{zone:1428}，必要时绕着树风筝他。",
	["{npc:14531}, a tauren, walks a loop in the rocks of northern {zone:1452}, north of {area:2255}. Talk to him and he becomes {npc:14535}. Within 30 yards of him {spell:23298} hits hard: keep your distance and kite him the whole fight, {spell:5118} on, south down the road. {spell:1978} on him adds {spell:23299}, extra Nature damage, so keep it ticking while you run; his {spell:23257} can be removed with {spell:19801}, but distance matters more. It is a long fight: bring mana potions and plan your kiting path."] = "{npc:14531}是牛头人，在{zone:1452}北部{area:2255}以北的岩石间绕圈行走。与他交谈后他会变成{npc:14535}。在他30码内{spell:23298}伤害很高：保持距离，整场风筝他，开着{spell:5118}沿路向南跑。在他身上保持{spell:1978}会附加{spell:23299}的额外自然伤害，所以边跑边维持它；他的{spell:23257}可以用{spell:19801}驱散，但距离更重要。这是一场持久战：带上法力药水，规划好风筝路线。",
	["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {object:164639}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536}是侏儒，在{zone:1451}西南角的{area:3428}大门附近走动。与他交谈后他会变成{npc:14530}。他变身时会用{spell:23272}狂暴：放一个{object:164639}（{spell:5384}），他就会脱战复位并去掉狂暴。{spell:2974}能长时间定住他；被定住期间他会恐惧你并放出甲虫（{npc:14761}）：用陷阱和{spell:2643}迅速杀掉它们，别被磨死。",
}

G["forever/class/mage/arcane-refreshment"] = {
	["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a {item:18249} (it drops from the imp Pusillin in the East wing; a {item:18594} also opens them; Blink no longer gets past). Other mages in your group can take it too: share it."] = "飞往羽月要塞（联盟）或{area:1099}（部落），再骑马到{zone:1444}中部的{area:2577}。{npc:14368}在图书馆（Athenaeum）里等候，可从西区抵达，也可从北区庭院大门进入，但需要{item:18249}（东区的小鬼普希林掉落；{item:18594}也能打开大门；闪现已无法穿过）。队伍里的其他法师也能接：可以共享。",
	["Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. {area:1758} hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets."] = "海多斯帕恩是一只57级精英水元素，住在扭木区（厄运之槌东区）：追赶小鬼普希林直到它转身战斗，清掉萨特房间，然后沿螺旋坡道下到水池。五人小队。冰霜法术对他无效，所以冰法改用火焰或奥术。{area:1758}会伤害10码内的所有人，远程要站远；血量降到四分之一时他会召唤小水元素。精华必掉；副本重置前他不会刷新。",
	["Mage"] = "法师",
	["{npc:14368}: {spell:10140}, and 200 Shen'dralar reputation"] = "{npc:14368}：{spell:10140}，以及200点辛德拉声望",
}

G["forever/class/priest/benediction"] = {
	["Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons."] = "装备{item:18646}，然后找到{npc:14494}，她是{zone:1423}西北山坡上的幽灵，在{area:2279}大门以西（如果她不出现，取下暗影之眼再重新戴上）。{quest:7621}只是对话；{quest:7622}一接就立即开始，所以先做好准备：满法力、强效法力药水、恶魔符文或黑暗符文、法力食物或{item:13931}，以及一组用于对付骷髅的{item:8956}或{item:13180}。",
	["Priest"] = "牧师",
	["Save 50 peasants before 15 die (the {object:179694} by the path counts the dead). They walk from the cave towards {npc:14494} in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first ({spell:552}), keep {spell:139} on the hurt ones, {spell:2061} the nearly dead, and kill skeletons as they spawn: one {spell:15237} of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and {npc:14494} is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back."] = "在15个农民死亡前救下50个（路边的{object:179694}会统计死者）。他们从洞穴一波波走向{npc:14494}，会感染疾病并召来骷髅和骷髅弓箭手。优先驱散发出紫光的疾病（{spell:552}），给受伤的农民保持{spell:139}，用{spell:2061}救快死的，骷髅一出现就杀掉：3级或更高的{spell:15237}一发就能杀掉它们，而圣油在它们打你时要跳两下。每波开始时给自己套盾；开启友方姓名板能更容易找出受伤的农民。朋友可以在你接任务前给你加增益，也可以治疗或驱散农民，但战斗开始后不能治疗或增益你、不能攻击骷髅、不能带宠物，否则会出现恶魔并杀死所有人。失败的话，{npc:14494}会消失一段时间（玩家报告从15分钟到两小时不等）；等她回来后再去找她交谈。",
	["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "史诗牧师法杖：来自{area:2717}的{spell:23101}、{npc:14494}的农民救援，然后是暗影之眼。",
	["The splinter needs {item:18665} as well. {npc:12397}, a world boss in the {zone:1419} (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first."] = "碎块还需要{item:18665}。{npc:12397}是{zone:1419}的世界首领（团队副本），必定掉落；那里的法力犬和末日守卫指挥官很少掉落（约3%和2%），冬泉谷的赫达林几乎不掉。它可以交易：先去拍卖行看看。",
	["Use the {item:18659} with both Eyes in your bags: {item:18608}"] = "背包里带着两只“眼睛”时使用{item:18659}：{item:18608}",
	["With the {item:18659}, {item:18646} and {item:18665} in your bags, use the splinter wherever you are: it becomes {item:18608}. Use {item:18608} to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown)."] = "背包里带着{item:18659}、{item:18646}和{item:18665}时，在任何地方使用碎块：它会变成{item:18608}。使用{item:18608}可将其变为暗影法杖咒逐，也能变回来（30分钟冷却）。",
	["{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it."] = "{item:18646}来自{object:179703}，即{area:2717}（40人团队副本）中{npc:12018}倒下后出现的宝箱（约一半几率开出）。{area:2717}的传送门在{area:1584}底部；完成“熔火之心的传送门”任务后（{item:18412}就在传送门旁），{area:254}里的{npc:14387}可以直接把你传送进去。没有暗影之眼，这条任务链的任何一环都无法开始：未装备它时你看不到{npc:14494}。",
	["{item:18646}: {area:2717}, through {area:254}"] = "{item:18646}：{area:2717}，经由{area:254}",
	["{npc:14387}: the way into {area:2717} once attuned"] = "{npc:14387}：完成开门任务后进入{area:2717}的途径",
}

G["forever/collectibles/mounts/neutral/warlock-felsteed"] = {
	["At 40 {npc:3326}, in the {object:172960}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40级时，{object:172960}里的{npc:3326}会让你去{area:392}找{npc:6251}。没看到任务？先完成地狱猎犬任务链：玩家反馈坐骑任务在其之后出现。",
	["At 40 {npc:4563}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}; {area:392} is a short flight from {zone:1454}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40级时，{object:36082}里的{npc:4563}会让你去{area:392}找{npc:6251}。从{zone:1420}的飞艇飞往{zone:1411}；{area:392}从{zone:1454}飞过去很近。没看到任务？先完成地狱猎犬任务链：玩家反馈坐骑任务在其之后出现。",
	["At 40 {npc:461}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40级时，{object:2101}中{object:2164}的地窖里的{npc:461}会让你去{area:392}找{npc:6251}。没看到任务？先完成地狱猎犬任务链：玩家反馈坐骑任务在其之后出现。",
	["At 40 {npc:5172}, by the warlock trainers in {zone:1455}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40级时，{zone:1455}的术士训练师旁的{npc:5172}会让你去{area:392}找{npc:6251}。没看到任务？先完成地狱猎犬任务链：玩家反馈坐骑任务在其之后出现。",
	["Warlock"] = "术士",
	["Your own mount at 40, summoned anywhere: no 100g riding training needed."] = "40级就能拥有专属坐骑，随处召唤：无需100金的骑术训练。",
	["{area:392} is the goblin port on the {zone:1413} coast, east of the {area:380}; from the Alliance side take the boat from {area:35}. {npc:6251} stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own {quest:3631} and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing."] = "{area:392}是{zone:1413}海岸上的地精港口，位于{area:380}以东；联盟一方从{area:35}坐船过去。{npc:6251}站在镇上山丘的小塔旁，不在下面的码头。先交任务，再接他自己的{quest:3631}并立刻交回：那会教你召唤坐骑。无需战斗，任务也不要任何物品。",
}

G["forever/collectibles/pets/baby-crocolisk"] = {
	["The {npc:3581} is a rare level 50 crocolisk, much tougher than a normal mob of its level. It swims {zone:1453}'s canals and appears at one of six spots, about two hours after it last died; the arrow takes you round them. Below 60, bring a group; at 60, a well-geared character can try it alone. It drops the {item:282047} about once in 70 kills, and the pet binds when picked up, so the Auction House never has it. Horde players can farm it too, but inside an enemy capital."] = "{npc:3581}是一只稀有的50级鳄鱼，比同级的普通怪物强硬得多。它在{zone:1453}的运河里游动，会在六个位置之一出现，上次死亡后约两小时刷新；箭头会带你逐个走遍这些位置。未满60级请组队；60级且装备良好的角色可以尝试单刷。它约每70次击杀掉落一次{item:282047}，宠物拾取即绑定，所以拍卖行永远买不到。部落玩家也能来刷，但这是在敌方主城里面。",
}

G["forever/collectibles/pets/narkk"] = {
	["{npc:2663}, the pirate supplier in {area:35}, sells two parrots (40s each), with no stock limit. He stands next to {npc:2664}, the cook. {area:35} is neutral: the boat from {area:392} and the Stranglethorn road both arrive there. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{area:35}的海盗供应商{npc:2663}出售两只鹦鹉（每只40银），不限量。他站在厨师{npc:2664}旁边。{area:35}是中立城镇：从{area:392}来的船和荆棘谷的道路都能到达。每个宠物物品使用时都会教会对应的小伙伴；之后目标仍保持勾选。",
}

G["forever/exploration/eastern-kingdoms-30-45"] = {
	["14 areas to discover here, levels 36-44. Flight paths: {area:16724} in the south-east (Alliance), {area:16743} in the middle (Horde)."] = "本段有14个区域可探索，等级36-44。飞行点：东南的{area:16724}（联盟）、中部的{area:16743}（部落）。",
	["From the south of the {zone:1418}, past {area:345}, a way leads down into the {zone:2548} by {area:16685}. (The {zone:2548} also open off northern Redridge through {area:2417}, and a ship runs from {area:977} in {zone:1446} to {area:16727}, the neutral goblin port on its coast.) {area:17780} is an ogre clan's outdoor dungeon."] = "从{zone:1418}南部经过{area:345}，有一条路向下通往{area:16685}旁的{zone:2548}。（{zone:2548}也可从赤脊山北部经{area:2417}进入，还有一艘船从{zone:1446}的{area:977}开往其海岸上的中立地精港口{area:16727}。）{area:17780}是一个食人魔氏族的野外副本。",
	["Or take the zeppelin from {zone:1454} or the {zone:1458} to {area:117}."] = "或者从{zone:1454}或{zone:1458}乘飞艇到{area:117}。",
	["Ride west out of the {zone:1435} through {zone:1430} (level 50+ creatures off the road) into {zone:1431} and take the road south into northern {zone:1434}."] = "从{zone:1435}向西骑出，穿过{zone:1430}（路外有50级以上的怪物），进入{zone:1431}，再沿路向南进入{zone:1434}北部。",
	["Starts in the {zone:1416}, north of {zone:1424}, and ends in {zone:1434}. 15 areas to discover here, levels 27-39."] = "从{zone:1424}以北的{zone:1416}开始，到{zone:1434}结束。本段有15个区域可探索，等级27-39。",
	["The {zone:1435} lies south of the {zone:2548}: swim south from {area:16725}, or walk through Redridge Pass, south of the {area:16737}."] = "{zone:1435}位于{zone:2548}以南：从{area:16725}向南游过去，或走{area:16737}以南的赤脊山隘口。",
	["{zone:1416} (1/2)"] = "{zone:1416}（1/2）",
	["{zone:1416} (2/2)"] = "{zone:1416}（2/2）",
	["{zone:1417} (1/2)"] = "{zone:1417}（1/2）",
