G["forever/legacy/legacy-challenges"] = {
	["Adventure: {quest:8999} (Alliance)"] = "冒险：{quest:8999}（联盟）",
	["Adventure: {quest:9007} (Horde)"] = "冒险：{quest:9007}（部落）",
	["Aku'mai"] = "阿库麦尔",
	["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "海加尔峰全部13个首领算一分。海加尔峰是 Forever 新增的20人团队副本，位于{zone:2482}顶部、诺达希尔附近，12月9日开放；其首领不在我们的数据中，所以13个全部击杀后请自行勾选。",
	["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "巴罗深渊全部8个首领算一分。巴罗深渊是 Forever 新增的10人团队副本，位于{zone:2482}之下，可从{zone:2482}、{zone:1452}或{area:1216}进入，12月9日开放；其首领不在我们的数据中，所以8个全部击杀后请自行勾选。",
	["Alzzin the Wildshaper"] = "荒野变形者奥兹恩",
	["Amnennar the Coldbringer"] = "寒冰使者阿姆纳",
	["Arcanist Doan"] = "奥法师杜安",
	["Archaedas"] = "阿扎达斯",
	["Archmage Arugal"] = "大法师阿鲁高",
	["Balnazzar"] = "巴纳扎尔",
	["Baron Rivendare"] = "瑞文戴尔男爵",
	["Bazzalan"] = "巴扎兰",
	["Bloodmage Thalnos"] = "血法师萨尔诺斯",
	["Charlga Razorflank"] = "查尔加·裂鬃",
	["Chief Ukorz Sandscalp"] = "酋长乌克兹·沙头皮",
	["City of Dalaran (Forever's, {zone:1416}): {npc:246020}"] = "达拉然城（Forever 专属，{zone:1416}）：{npc:246020}",
	["Darkmaster Gandling"] = "黑暗院长加丁",
	["Durgen Dirgehammer"] = "杜根·挽歌之锤",
	["Edwin VanCleef"] = "埃德温·范克里夫",
	["Emperor Dagran Thaurissan"] = "达格兰·索瑞森大帝",
	["Exalted with each of the four battleground factions is worth a point. Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation and Darkspear Islands Reputation (Forever's new battleground, open from level 30). The Diplomat Legacy perk increases reputation gains."] = "与四个战场阵营的声望都达到崇拜，各算一分。请参照 Polestar 声望指南《战歌峡谷声望》《阿拉希盆地声望》《奥特兰克山谷声望》和《暗矛群岛声望》（Forever 新增战场，30级开放）。传承特长“外交家”会提高声望获取。",
	["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "用同一个角色探索完整张世界地图算一分，并且还能解锁传承系统。必须在同一角色上完成。Forever 的新区域也是地图的一部分：{zone:2548}、{zone:2652}和{zone:2482}（60级区域）。",
	["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet."] = "请参照 Polestar 探索指南：《探索：东部王国 1-30》《30-45》和《45-60》，以及《探索：卡利姆多 1-30》《30-45》和《45-60》。它们会随你发现记录每个区域。《探索：泽弗拉斯岛》涵盖天裔岛屿；其地图是否计入此挑战尚未确认。",
	["General Drakkisath"] = "达基萨斯将军",
	["Herod"] = "赫罗德",
	["High Inquisitor Whitemane"] = "高阶检察官怀特迈恩",
	["Killing {npc:10184} is a point. {area:2159} is a 40-player raid in {zone:1445}, open from 9 December. Every raider needs the {item:16309} in the bags: the Alliance chain starts with Dragonkin Menace in the {zone:1428}, the Horde chain with Blood and Thunder in {area:340} ({zone:1418}); both end in Upper Blackrock Spire with {npc:10363}."] = "击杀{npc:10184}算一分。{area:2159}是{zone:1445}中的40人团队副本，12月9日开放。每位团员都需要在包里带着{item:16309}：联盟任务链从{zone:1428}的“龙类的威胁”开始，部落任务链从{area:340}（{zone:1418}）的“血与雷”开始；两条链都在黑石塔上层找{npc:10363}结束。",
	["King Gordok"] = "戈多克大王",
	["Mekgineer Thermaplugg"] = "机械师瑟玛普拉格",
	["Mutanus the Devourer"] = "吞噬者穆坦努斯",
	["Onyxia"] = "奥妮克希亚",
	["Overlord Wyrmthalak"] = "维姆萨拉克领主",
	["Prince Tortheldrin"] = "托塞德林王子",
	["Princess Theradras"] = "瑟莱德丝公主",
	["Relic Guardian"] = "圣物守卫者",
	["Shade of Eranikus"] = "伊兰尼库斯的阴影",
	["Shade of the Archmage"] = "大法师的阴影",
	["The final boss of every level 15-25 dungeon earns one point together. {area:2437} and Forever's {area:16919} (in {zone:1455}) count as one: either final boss does. Tick each boss off when you kill it, and check the in-game Legacy panel for the list."] = "所有15-25级副本的最终首领合计算一分。{area:2437}与 Forever 的{area:16919}（位于{zone:1455}）合为一个：任一最终首领都算。每击杀一个首领就勾选它，完整列表请查看游戏内的传承面板。",
	["The final boss of every level 26-45 dungeon earns one point together. The Drowned City and {area:17780} (in the {zone:2548}) are new in Forever and not in our data: tick them off yourself."] = "所有26-45级副本的最终首领合计算一分。沉没之城和{area:17780}（位于{zone:2548}）是 Forever 新增内容，不在我们的数据中：请自行勾选。",
	["The final boss of every level 46-60 dungeon earns one point together. Alcaz Prison, {area:1216} and the {area:16985} are new in Forever and not in our data: tick them off yourself."] = "所有46-60级副本的最终首领合计算一分。阿尔卡兹监狱、{area:1216}和{area:16985}是 Forever 新增内容，不在我们的数据中：请自行勾选。",
	["The {npc:16042} questline is a point. It is the level 60 dungeon-set chain, from An Earnest Proposition to your class's {quest:8999}: {npc:16013} ({zone:1455}) or {npc:16012} ({zone:1454}) send you through In Search of Anthion and Anthion's Parting Words to {npc:16033} at {area:254}, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and {quest:8995} end with {quest:8996}. {quest:8997} then leads to {quest:8999}."] = "{npc:16042}的任务链算一分。这是60级副本套装任务链，从“诚挚的提议”一直到本职业的{quest:8999}：{npc:16013}（{zone:1455}）或{npc:16012}（{zone:1454}）会通过“寻找安东尼”和“安东尼的临别赠言”把你派去找{area:254}的{npc:16033}；从他那里接的“火焰三王”、瓦萨拉克领主护符的左块与右块、“最后的准备”和{quest:8995}，最终以{quest:8996}结束。{quest:8997}随后引出{quest:8999}。",
	["Viktor the Vile"] = "卑劣的维克托",
	["the final boss of Alcaz Prison"] = "阿尔卡兹监狱的最终首领",
	["the final boss of the Drowned City"] = "沉没之城的最终首领",
	["the final boss of the {area:16985}"] = "{area:16985}的最终首领",
	["the final boss of {area:1216}"] = "{area:1216}的最终首领",
	["the final boss of {area:17780}"] = "{area:17780}的最终首领",
	["{area:153} (Forever's, {zone:1420}): {npc:256035}"] = "{area:153}（Forever 专属，{zone:1420}）：{npc:256035}",
	["{area:16919}: {npc:261319} (or {area:2437})"] = "{area:16919}：{npc:261319}（或{area:2437}）",
	["{area:17732} (Forever's): {npc:260326}"] = "{area:17732}（Forever 专属）：{npc:260326}",
	["{area:2437}: {npc:11519} (or {area:16919})"] = "{area:2437}：{npc:11519}（或{area:16919}）",
	["{npc:16012} then offers your class's {quest:9007}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16012}随后会发布本职业的{quest:9007}，即挑战的最后一个任务：它会拿走你职业的副本套装头盔和胸甲，并将其升级。",
	["{npc:16013} then offers your class's {quest:8999}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16013}随后会发布本职业的{quest:8999}，即挑战的最后一个任务：它会拿走你职业的副本套装头盔和胸甲，并将其升级。",
}

G["forever/professions/fishing"] = {
	["Any {skill:356} trainer of your faction teaches Apprentice {skill:356} (character level 5, 1s); the arrow picks the nearest, and every starting area has one on its lake or shore. Buy a {item:6256} (23c) from a trade goods or fishing vendor and equip it (you can only fish with a pole in your hands), and two or three Shiny Baubles (+25, 50c each): a lure adds its bonus to your skill for ten minutes, so fewer fish get away at the start. If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:356}, handed in to the fishing trainer it names at skill 20 for the {spell:1229745} recipe."] = "本阵营任意{skill:356}训练师都教初级{skill:356}（角色5级，1银）；箭头会指向最近的一位，每个新手地区湖畔或岸边都有一位。从杂货商或钓鱼供应商处买一根{item:6256}（23铜）并装备（必须手持鱼竿才能钓鱼），再买两三个闪亮的鱼饵（+25，每个50铜）：鱼饵会在十分钟内提高你的技能，开荒时鱼更难跑掉。如果你为了“户外活动”在新手地区的营火旁坐过，那里的露营指南还会提供“露营入门：{skill:356}”，技能20时交给它指定的钓鱼训练师，可得{spell:1229745}配方。",
	["Expert {skill:356} (cap 225) is a book, not a trainer rank: {npc:2626} sells {item:16083} (1g) on the lowest dock of {area:35}, at the south tip of {zone:1434}, to both factions. Buy it and read it; it needs skill 125 and level 20. At level 20 the safe way in is the boat from {area:392} in {zone:1413}, not the road through Stranglethorn. He also sells {item:6532} (+75 from skill 100, 2s 50c each), the lure for the rest of the way."] = "高级{skill:356}（上限225）是一本书，而非训练师等级：{npc:2626}在{zone:1434}南端{area:35}最下面的码头向双方阵营出售{item:16083}（1金）。买下并阅读；它需要技能125和角色20级。20级时安全的进入方式是乘{zone:1413}中{area:392}的船，而不是走荆棘谷的道路。他还出售{item:6532}（技能100起可用，+75，每个2银50铜），是后续升级用的鱼饵。",
	["Fish along the coast of {zone:1443} ({area:598} in the north-west, or the shore west of {area:2408}) until you catch a {item:16968}: about one catch in five there brings it up, and it bites nowhere else. At skill 225 nothing gets away here."] = "在{zone:1443}海岸（西北的{area:598}，或{area:2408}以西的岸边）钓鱼，直到钓上{item:16968}：那里约每五竿出一竿，别处不会咬钩。技能225时这里不会跑鱼。",
	["Fish along the {area:2521} in {zone:1444} (south-east of {area:2577}) until you catch a {item:16967}: about one catch in five there brings it up, and it bites nowhere else. This water loses fish below skill 300: at 225 most get away, so put {item:6532} (+75) on the pole first."] = "在{zone:1444}的{area:2521}（{area:2577}东南）钓鱼，直到钓上{item:16967}：那里约每五竿出一竿，别处不会咬钩。这片水域在技能300以下会跑鱼：225时大部分会跑掉，所以先给鱼竿装上{item:6532}（+75）。",
	["Fish along the {area:300} (the east shore of {zone:1435}) until you catch a {item:16970}: about one catch in five there brings it up, and it bites nowhere else. At skill 225 nothing gets away here."] = "在{area:300}（{zone:1435}东岸）钓鱼，直到钓上{item:16970}：那里约每五竿出一竿，别处不会咬钩。技能225时这里不会跑鱼。",
	["Fish along {zone:1434}'s {area:301} (the west shore) until you catch a {item:16969}: about one catch in five there brings it up, and it bites nowhere else. At skill 225 nothing gets away here."] = "在{zone:1434}的{area:301}（西岸）钓鱼，直到钓上{item:16969}：那里约每五竿出一竿，别处不会咬钩。技能225时这里不会跑鱼。",
	["Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast {skill:356} from your spellbook, click the bobber when it splashes. Keep the fish: they are your first {skill:185} ingredients."] = "在此钓到技能50，约50竿：75以下每竿都涨技能。从法术书施放{skill:356}，浮标下沉时点击它。留着鱼：它们是你最早的{skill:185}材料。",
	["Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast {skill:356} from your spellbook, click the bobber when it splashes. Keep the fish: they are your first {skill:185} ingredients. Fish get away here below skill 25; a lure on the pole adds to your skill for ten minutes and closes the gap."] = "在此钓到技能50，约50竿：75以下每竿都涨技能。从法术书施放{skill:356}，浮标下沉时点击它。留着鱼：它们是你最早的{skill:185}材料。技能25以下这里会跑鱼；给鱼竿装鱼饵可在十分钟内提高技能，弥补差距。",
	["Fish the pools along the coast here (eels, snappers, wreckage) until skill 300, about 650 catches (one in seven raises the skill at 225, one in ten by 300). Harder water levels no faster: a catch counts the same anywhere. From skill 225 this water loses no fish, so no lure is needed. The {item:6533} (+100 from skill 100, 2s 50c) and {item:6532} are for harder water and rare fish, not for skill."] = "在此沿岸的鱼群（鳗鱼、鲷鱼、残骸）中钓鱼，直到技能300，约650竿（225时约七竿涨一点，300时约十竿一点）。更高级的水域并不会更快：任何地方一竿的收益都一样。技能225起这片水域不会跑鱼，所以不需要鱼饵。{item:6533}（技能100起可用，+100，2银50铜）和{item:6532}是用于更高级水域和稀有鱼的，不是用来练技能的。",
	["Fish the pools and open water here until skill 125, about 120 catches: from 75 a catch raises the skill less often (about one in two by 100, one in three by 125). Pools (floating wreckage, schools of fish) also give extra loot. {item:6530} (+50 from skill 50, 1s each) are twice as strong as a {item:6529}. The {item:6365} (+5 from skill 10, 9s 1c) is in limited stock at fishing vendors: buy it when you see it. Fish get away here below skill 75; a lure on the pole adds to your skill for ten minutes and closes the gap."] = "在此的鱼群和开阔水域钓鱼，直到技能125，约120竿：从75起涨点变慢（100时约两竿一点，125时约三竿一点）。鱼群（漂浮残骸、鱼群）还会给额外战利品。{item:6530}（技能50起可用，+50，每个1银）效果是{item:6529}的两倍。{item:6365}（技能10起可用，+5，9银1铜）在钓鱼供应商处限量出售：看到就买。技能75以下这里会跑鱼；给鱼竿装鱼饵可在十分钟内提高技能，弥补差距。",
	["Fish the pools here until skill 225, about 500 catches: one in three raises the skill at 125, one in seven by 225, so this is the long stretch. Forever's second camping item, the {item:279965} (from skill 140), is a blueprint that drops from Gelihast in {area:2797}. Fish get away here below skill 150; a lure on the pole adds to your skill for ten minutes and closes the gap."] = "在此的鱼群钓鱼，直到技能225，约500竿：125时约三竿一点，225时约七竿一点，所以这是最漫长的一段。Forever 的第二个露营物品{item:279965}（技能140起）是图纸，由{area:2797}的格里哈斯特掉落。技能150以下这里会跑鱼；给鱼竿装鱼饵可在十分钟内提高技能，弥补差距。",
	["Journeyman {skill:356} raises the cap to 150; it needs skill 50 and character level 10 (Forever's sniffed trainer lists ask for that level), and costs 5s. The arrow picks the nearest {skill:356} trainer of your faction. {spell:1229745}, Forever's camping item for {skill:356} (from skill 20, 1s or free from Camping 101: {skill:356}), is a {item:6291} in an {item:3371}: it gives no skill, but placed beside a campfire it gives everyone at the camp a buff for an hour."] = "中级{skill:356}把上限提高到150；需要技能50和角色10级（Forever 抓取的训练师列表中要求该等级），花费5银。箭头会指向本阵营最近的{skill:356}训练师。{spell:1229745}是 Forever 的{skill:356}露营物品（技能20起，1银，或从“露营入门：{skill:356}”免费获得），即装在{item:3371}里的{item:6291}：它不给技能，但放在营火旁能为一小时内的所有营地成员提供增益。",
	["Sen'jin coast"] = "森金海岸",
	["{area:16638} shore"] = "{area:16638}岸边",
	["{npc:12919} fishes from the shore of a small island off the east coast, south of Theramore; swim over from the coast."] = "{npc:12919}在东海岸外一座小岛的岸边钓鱼，位于塞拉摩以南；从海岸游过去。",
