G["forever/reputation/hydraxian-waterlords"] = {
	["Ancient Core Hound"] = "上古熔火犬",
	["At Revered the Duke gives you the {item:22754}: it does the {item:17333}'s work and is not used up, so you never come back for another vial."] = "崇敬时公爵会给你{item:22754}：它能起到{item:17333}的作用，而且不会消耗，所以你不用再回来领新的瓶子。",
	["Back to {npc:13278}. {quest:6823} is done the moment you are Honored."] = "回到{npc:13278}。一到尊敬，{quest:6823}就完成了。",
	["Baron Geddon"] = "迦顿男爵",
	["Desert Rumbler"] = "沙漠奔行者",
	["Dust Stormer"] = "尘暴元素",
	["Dust Stormers and Desert Rumblers drift around the {area:2740} in the north-west of {zone:1451}. Each kill also pays 5 reputation while you are Neutral or Friendly, so stay if you mean to farm (next steps)."] = "尘暴元素和沙漠奔行者在{zone:1451}西北的{area:2740}一带游荡。在中立或友善阶段，每杀一个还给5点声望，所以打算刷的话就留在这里（见后续步骤）。",
	["Elementals to Honored"] = "元素生物到尊敬",
	["Firelord"] = "火焰领主",
	["Firewalker"] = "火焰行者",
	["Flameguard"] = "烈焰守卫",
	["Garr"] = "加尔",
	["Gehennas"] = "基赫纳斯",
	["Golemagg the Incinerator"] = "焚化者古雷马格",
	["Hand in the hands, then dive under the surf at the southern foot of the island: {object:179551} holds your ring and pays the only quest reputation the Waterlords give, 200. From now on, while you are Honored or better, the Duke hands you {item:17333}: pour it on a rune in the {area:2717} to douse it. With every rune doused, {npc:12018} comes out, and after him {npc:11502}."] = "交掉那些首领之手，然后潜入岛南端脚下的海浪下：{object:179551}里放着你的戒指，并给出水元素领主唯一的任务声望，200点。从此以后，只要你达到尊敬或更高，公爵就会给你{item:17333}：把它浇在{area:2717}的符文上将其熄灭。所有符文都熄灭后，{npc:12018}会出现，之后是{npc:11502}。",
	["Honored to Revered is 12,000 reputation. The trash still counts, so a full clear pays about 3,360 plus 700 from the seven bosses, 150 from {npc:11988} and 200 from {npc:11502}: about three clears. {npc:9017} (15) and {npc:9816} (50) count too while you are Honored. The trash stops at 11,999 of 12,000 Honored; the bosses carry you over."] = "尊敬到崇敬需要12,000声望。小怪仍然计数，所以一次全清约给3,360，加上七个首领的700、{npc:11988}的150和{npc:11502}的200：大约三次全清。处于尊敬阶段时，{npc:9017}（15）和{npc:9816}（50）也计数。小怪在尊敬11,999/12,000处停止；靠首领把你带过去。",
	["Huricanian"] = "飓风元素",
	["Lava Elemental"] = "熔岩元素",
	["Lava Surger"] = "熔岩奔腾者",
	["Lord Incendius"] = "因森迪斯领主",
	["Lucifron"] = "鲁西弗隆",
	["Magmadar"] = "玛格曼达",
	["Molten Giant"] = "熔火巨人",
	["Neutral to Honored is 9,000 reputation, and {quest:6823} asks for Honored. One {area:2717} clear pays about 4,000 of it. Without a raid it comes from the elementals: 5 per {npc:11744}, {npc:11746} or {npc:7032} (the {zone:1428}), about 1,800 kills from Neutral. They stop at 5,999 of 6,000 Friendly, one point short, so the last point needs a kill that still counts there: {npc:14478}, a rare air elemental in the {area:2740} (25), or {npc:9017} at the {object:174825} in {area:1584} (15, a five-player dungeon). Those two and {npc:9816} keep paying through Honored as well."] = "中立到尊敬需要9,000声望，而{quest:6823}要求尊敬。一次{area:2717}全清约给其中4,000。不组团的话就靠元素生物：{npc:11744}、{npc:11746}或{npc:7032}（{zone:1428}）每只5点，从中立起约需1,800次击杀。它们在友善5,999/6,000处停止，差一点，所以最后一点需要一次在那里仍计数的击杀：{area:2740}的稀有空气元素{npc:14478}（25点），或{npc:9017}在{area:1584}的{object:174825}处（15点，五人副本）。后两者和{npc:9816}在尊敬阶段也继续给声望。",
	["Ragnaros"] = "拉格纳罗斯",
	["Reputation · Raids and dungeons"] = "声望 · 团队副本与地下城",
	["Revered to Exalted is 21,000 reputation. The trash has stopped, but all nine bosses still pay while you are Revered: 100 each from the seven, 150 from {npc:11988} and 200 from {npc:11502}, 1,050 a clear: about 20 clears. The seven stop at 20,999 of 21,000 Revered, so the last point comes from {npc:11988} or {npc:11502}, and from Exalted on only those two pay."] = "崇敬到崇拜需要21,000声望。小怪已不再计数，但在崇敬阶段九个首领仍然给：七个各100，{npc:11988}给150，{npc:11502}给200，一次全清1,050：大约20次全清。那七个在崇敬20,999/21,000处停止，所以最后一点来自{npc:11988}或{npc:11502}；到崇拜之后只有这两个还给。",
	["Shazzrah"] = "沙斯拉尔",
	["Sulfuron Harbinger"] = "萨弗隆先驱者",
	["The {item:22754}"] = "{item:22754}",
	["Use the {item:17310} on a {npc:8521} or a {npc:8522}: it turns into a {npc:13279}. Kill the surge and loot its {item:17309}. Twelve are needed, and the vial must still be in your bags at the turn-in."] = "对{npc:8521}或{npc:8522}使用{item:17310}：它会变成一个{npc:13279}。杀掉它并拾取它的{item:17309}。需要十二个，而且交任务时瓶子必须还在你的背包里。",
	["{area:2717} to Exalted"] = "{area:2717}到崇拜",
	["{area:2717} to Revered"] = "{area:2717}到崇敬",
	["{item:17310}, on the poisoned elementals"] = "{item:17310}，用在被污染的元素生物上",
	["{item:17332}: raid of 40"] = "{item:17332}：40人团队副本",
	["{item:17333} to douse the {area:2717}'s runes, the reusable {item:22754} at Revered and a fire resistance ring."] = "{item:17333}用来熄灭{area:2717}的符文，崇敬时可换的永久物品{item:22754}，以及一枚火焰抗性戒指。",
