	["{npc:12264}, 100"] = "{npc:12264}，100",
	["{npc:13278} stands on a small island off the east coast of {zone:1447}; swim out to him. Everyone starts Neutral with the Waterlords, and nearly all of their reputation comes from killing the servants of fire, air and earth: the quests themselves pay nothing until the last one. Take both quests: the chain goes on only when both are done. Everything past Honored happens in the {area:2717}, a raid of 40 that is not among the first raids Blizzard has announced for Forever; until it opens, Honored is as far as the Waterlords go. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%."] = "{npc:13278}站在{zone:1447}东海岸外的一座小岛上；游过去找他。所有人一开始与水元素领主都是中立，而他们的声望几乎全部来自击杀火焰、空气和土元素的仆从：任务本身直到最后一个都不给声望。两个任务都接：只有两个都完成，任务链才会继续。尊敬之后的一切都在{area:2717}中进行——那是一个40人团队副本，并不在暴雪为 Forever 公布的首批团队副本之列；在它开放之前，水元素领主的声望最多到尊敬。本篇攻略的数字不含传承特长“外交家”，它最多可加10%。",
	["{npc:14387} in {area:254} attunes you to the {area:2717}: bring him a {item:18412} from beside the {area:2717}'s portal at the bottom of {area:1584}. Once attuned, he can send you straight into the {area:2717}."] = "{area:254}的{npc:14387}能让你与{area:2717}同调：给他带一个{item:18412}，它就在{area:1584}底部{area:2717}传送门旁。同调之后，他可以直接把你送进{area:2717}。",
	["{npc:14478}, rare, 25"] = "{npc:14478}，稀有，25",
	["{npc:9017}, {area:1584}: 15, group up"] = "{npc:9017}，{area:1584}：15点，组队前往",
	["{npc:9816} is a boss in Upper Blackrock Spire, inside {area:254}: a group of up to ten, and someone needs the {item:12344} to open the door. He drops the Eye and pays 50 reputation per kill up to 11,999 of 12,000 Honored. {npc:9017} in {area:1584} pays 15 the same way."] = "{npc:9816}是{area:254}内黑石塔上层的首领：最多十人，需要有人带着{item:12344}才能开门。他掉落“眼睛”，并且每次击杀给50声望，直到尊敬11,999/12,000。{area:1584}的{npc:9017}以同样方式给15点。",
	["{quest:6821}: raid of ten"] = "{quest:6821}：十人团队副本",
	["{quest:6822} is a raid of 40. Kill one {npc:11658}, {npc:11668}, {npc:11673} and {npc:12101} for {npc:13278}. Every elemental there pays: Firewalkers, Flameguards, Lava Elementals, Lava Reavers and Molten Destroyers 40, Firelords, Lava Surgers, Molten Giants and Ancient Core Hounds 20, up to 11,999 of 12,000 Honored; about 3,360 for a full clear of the trash. The bosses pay 100 each ({npc:11988} 150, {npc:11502} 200)."] = "{quest:6822}是40人团队副本。为{npc:13278}各杀一只{npc:11658}、{npc:11668}、{npc:11673}和{npc:12101}。那里每个元素生物都给声望：火焰行者、烈焰守卫、熔岩元素、熔岩掠夺者和熔火摧毁者40点，火焰领主、熔岩奔腾者、熔火巨人和上古熔火犬20点，直到尊敬11,999/12,000；全清小怪约3,360点。首领各给100（{npc:11988}150，{npc:11502}200）。",
}

G["forever/class/mage/mages-wand"] = {
	["Back to {npc:6546}. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire)."] = "回到{npc:6546}。两个任务都交完后，她会开始仪式：等几秒，再与她交谈，挑选你的魔杖：冰怒（冰霜）、虚空之力（奥术）或怒焰（火焰）。",
	["Mage"] = "法师",
	["The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of {area:321}; every kind of them drops a {item:7273} about two times in five: you need ten. Then go to the {area:336} (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the {item:7272} forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more."] = "枯木巨魔（30-36级）占据阿拉希东南部和{area:321}以南的村庄，各种类都有约五分之二的几率掉落{item:7273}：你需要十个。然后去{area:336}（外圈，不是内圈）。三只元素生物（33-39级）围着中央石柱：一次拉一只，先把它们清掉。站在中央石旁使用图腾棍；约十秒后石上会形成{item:7272}：点击它。若在拾取前死亡，荆棘和棍子都会消失，需要再凑十个。",
	["Tirth sold the book to the Scarlet Crusade. The {area:796} stands in north-eastern {zone:1420}; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in {npc:6487}'s round room: on the left-hand shelf as you face his room, next to the {item:5535}. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read."] = "提尔斯把书卖给了血色十字军。{area:796}位于{zone:1420}东北；五人组队走图书馆翼。书在最里面那条长走廊的尽头，即通向{npc:6487}圆形房间的那条：面朝他房间时左手边的书架上，{item:5535}旁边。拿书架上凸出来的那本厚重的蓝色高亮书；放大镜光标表示只能阅读的书。",
	["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes."] = "提尔斯的学徒是“普拉基”约翰逊，一只灰色小鸡，在赛道瞭望塔脚下啄食；晚上输入 /target plucky。选中他并输入 /beckon（不是 /chicken 或 /wave）：他会短暂变回人形。与他交谈，问那句话。不要攻击他。若他不见了，5分钟内会回来。",
	["Witherbark trolls and the {item:7272}"] = "枯木巨魔与{item:7272}",
	["at the middle stone of the {area:336}"] = "在{area:336}的中央石旁",
	["{npc:5497} at the top of the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{zone:1453}的{object:2101}（巫师圣殿）顶层的{npc:5497}会派你去找{npc:6546}；{zone:1455}的宾克给同样的任务。",
	["{npc:5885}, one of {zone:1454}'s mage trainers in {object:173161}, sends you to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{object:173161}里{zone:1454}的法师训练师之一{npc:5885}会派你去找{npc:6546}；{zone:1458}的{npc:4568}和{zone:1456}的{npc:3048}给同样的任务。",
	["{npc:6546} also wants one {item:1529}, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of {area:271} drop one about every fifth kill. Do not sell it to a vendor by mistake."] = "{npc:6546}还要一颗{item:1529}，一颗绿宝石。矿工有时在矿脉中挖到；拍卖行有售；{area:271}西南海岸的碎鳍海岸行者约每五杀掉一个。别误卖给了商人。",
	["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the {zone:1413}. Her cottage is no refuge: mobs follow you inside. Take both her quests."] = "{npc:6546}是个隐士，住在塞拉摩以西沼泽深处的小屋，就在{area:508}以北。38-41级精英在她农场东侧游荡，游水过来会遇上42级的泥壳鱼人：从{zone:1413}沿路自西面进入。她的小屋不是避难所：怪物会跟进来。把她两个任务都接了。",
}

G["forever/class/rogue/the-eye-of-bhossca"] = {
	["Rogue"] = "盗贼",
	["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "修道院位于{zone:1420}最东北部。独自进去，不要组队。进门前，从修道院后方马厩的补给箱里拿取{spell:427592}并穿上；潜行和可疑举动会移除它，所以每换一翼后重新穿上。在墓地，赎罪大厅（第一个大房间）里，对{npc:4293}或血色传令官使用{spell:921}，取得{item:210963}。在图书馆，用它打开阅览室的私人信箱，阅读机密信件。它会让你回到墓地，坐在两座雕像之间的两条长凳上。留意机关的消息，然后从石柜中取走{item:210968}：一名精英守在石柜旁，身后还有巡逻，但从北面陵墓旁转动视角，直到箱子显现，就能穿墙点击它（互动键也行）。一名精英鬼魂在陵墓附近游走；它边缘的残片能让你避开它的路线。然后回到图书馆，取得上锁的圣物箱和那只眼睛。不要一路打穿副本。",
}

G["forever/collectibles/mounts/neutral/galestrider"] = {
	["Any race can buy Galestriders, but riding one also takes {spell:1285849}, which only the Skyborne get with {skill:762}. Other races can learn it too, but how is not known yet: in Classic another race's riding needed Exalted with its home faction, here the High Order (Alliance) or the Windshapers (Horde). Ask {npc:265756} before you buy."] = "任何种族都能买风行者，但骑乘还需要{spell:1285849}，只有天裔在{skill:762}中才能获得。其他种族也能学，但方法尚不清楚：经典旧世中，其他种族骑乘需要与所属阵营达到崇拜，这里则是高等议会（联盟）或风塑者（部落）。购买前先问问{npc:265756}。",
	["Galestriders need level 40 and {skill:762}. Train it at your own race's riding trainer; see the Level 40 mount guides for where."] = "风行者需要40级和{skill:762}。到自己种族的骑术训练师处学习；具体位置见40级坐骑指南。",
	["Skyborne learn {skill:762} from {npc:265756} himself for 100g, and it comes with a Galestrider. He stands at the {area:17684} in {area:16638}, near the skyboat docks."] = "天裔在{npc:265756}本人那里花100金学习{skill:762}，并附赠一匹风行者。他站在{area:16638}的{area:17684}，靠近飞船码头。",
	["{npc:265756} is at the {area:17684} in {area:16638}, the island's harbour town, near the skyboat docks. The Forever client lists each Galestrider at 20g; choose one."] = "{npc:265756}在{area:16638}的{area:17684}，那是岛上的港口镇，靠近飞船码头。Forever客户端标价每匹风行者20金；挑一匹吧。",
	["{npc:265756}, riding trainer"] = "{npc:265756}，骑术训练师",
	["{skill:762} with {npc:265756}"] = "向{npc:265756}学习{skill:762}",
	["{spell:1285849} for other races"] = "其他种族学{spell:1285849}",
}

G["forever/collectibles/mounts/neutral/spectral-bear"] = {
	["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, professions, PvP, exploring) is worth one, and every point the account earns counts here, spent or not. The Legacy Challenges guide plans them. The Progress Track gives the {item:281060} at 15, the {npc:268840} at 25, the {item:277717} at 40 and the reins at 55. Claim each one from {npc:6791} at the inn in {area:392}, on the {zone:1413} coast: he offers a \"Legacy Reward\" quest once you have the points."] = "传承点数是账号通用的：每个传承挑战（职业达到25、45和60级，专业，PvP，探索）值一点，账号赚到的每一点都算在这里，无论是否花掉。传承挑战指南会帮你规划。进度轨道在15点时给{item:281060}，25点时给{npc:268840}，40点时给{item:277717}，55点时给缰绳。每一项都从{area:392}旅店里的{npc:6791}处领取，该地在{zone:1413}海岸：点数够了以后他会提供“传承奖励”任务。",
	["The bear runs at full speed: riding it needs level 60 and Journeyman {skill:762} (Forever client), from your race's riding trainer; see the Level 60 mount guides."] = "这头熊按全速奔跑：骑乘需要60级和中级{skill:762}（Forever客户端），到自己种族的骑术训练师处学习；具体位置见60级坐骑指南。",
	["from {npc:6791}"] = "来自{npc:6791}",
}

