G["forever/professions/enchanting"] = {
	["1 {item:5500} for {item:11130}: open the Giant Clams at the marked spot, or buy it at the Auction House."] = "1个{item:5500}，用于{item:11130}：在标记处打开巨型蛤蜊，或在拍卖行购买。",
	["34 {item:8831} for {item:20747}: {skill:182}: {item:8831} (skill 210) in {zone:1425} (40-50), {zone:1444} (40-50) and {zone:1447} (45-55); or the Auction House. The densest patch of {item:8831} in {zone:1425} is marked."] = "34个{item:8831}，用于{item:20747}：{skill:182}：{item:8831}（技能210）产自{zone:1425}（40-50）、{zone:1444}（40-50）和{zone:1447}（45-55）；或在拍卖行购买。{zone:1425}中{item:8831}最密集的一片已标记。",
	["34 {item:8831} for {item:20747}: {skill:182}: {item:8831} (skill 210) in {zone:1425} (40-50), {zone:1444} (40-50) and {zone:1447} (45-55); or the Auction House. The densest patch of {item:8831} in {zone:1444} is marked."] = "34个{item:8831}，用于{item:20747}：{skill:182}：{item:8831}（技能210）产自{zone:1425}（40-50）、{zone:1444}（40-50）和{zone:1447}（45-55）；或在拍卖行购买。{zone:1444}中{item:8831}最密集的一片已标记。",
	["Apprentice {skill:333} lets you craft up to 75 for 10c, at any character level. Not every {skill:333} trainer teaches it: Alliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:5157} ({zone:1455}), {npc:11072} ({zone:1429}), {npc:11070} ({zone:1457}), {npc:1317} ({zone:1453}), {npc:257020} (Zephras Isle), {npc:4213} ({zone:1457}), {npc:11065} ({zone:1455}), {npc:5158} ({zone:1455}) and {npc:7949} ({zone:1444}); Horde {npc:257004} (Zephras Isle), {npc:3345} ({zone:1454}), {npc:11074} ({zone:1442}), Jhag ({zone:1454}), {npc:4616} ({zone:1458}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:3011} ({zone:1456}) and {npc:5695} ({zone:1420}). The arrow picks the nearest of your faction. Buy a {item:6217} and {item:247786} from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from {npc:11072} ({area:91}, {zone:1429}) and A Pain in the Neck from {npc:266881} ({area:367}, {zone:1411}). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 {item:10940} to gather or buy."] = "初级{skill:333}让你在任何角色等级下花10铜把技能练到75。并非每位{skill:333}训练师都教：联盟有{npc:3606}（{zone:1438}）、{npc:11068}（{zone:1453}）、{npc:257004}（泽弗拉斯岛）、{npc:5157}（{zone:1455}）、{npc:11072}（{zone:1429}）、{npc:11070}（{zone:1457}）、{npc:1317}（{zone:1453}）、{npc:257020}（泽弗拉斯岛）、{npc:4213}（{zone:1457}）、{npc:11065}（{zone:1455}）、{npc:5158}（{zone:1455}）和{npc:7949}（{zone:1444}）；部落有{npc:257004}（泽弗拉斯岛）、{npc:3345}（{zone:1454}）、{npc:11074}（{zone:1442}）、Jhag（{zone:1454}）、{npc:4616}（{zone:1458}）、{npc:11067}（{zone:1458}）、{npc:11071}（{zone:1456}）、{npc:257020}（泽弗拉斯岛）、{npc:3011}（{zone:1456}）和{npc:5695}（{zone:1420}）。箭头会指向本阵营最近的一位。从附魔用品供应商处买一个{item:6217}和一个{item:247786}（主城和泽弗拉斯岛都有；新手地区的训练师身边没有，下一步的箭头会指向最近的一位）。从现在起，把不穿的绿装全部分解：尘和精华就是这么来的。两个新手任务会用任务物品教你分解：“附魔入门课”来自{npc:11072}（{zone:1429}的{area:91}），“脖子上的麻烦”来自{npc:266881}（{zone:1411}的{area:367}）。1-75大约花50铜的配方钱和4银44铜的商人货物，外加51个{item:10940}，需自行采集或购买。",
	["Artisan raises the cap from 225 to 300 for 5g (Classic's price; Forever's is not in the data); it needs {skill:333} 200 and character level 35, so you can take it on any visit from 200. {npc:11073} teaches Artisan {skill:333} inside the {area:1517} dungeon ({zone:1418}); bring a group. Learn now: {spell:13815} (from 210). 225-300 takes about 2g 20s of recipes and 1g 70s of vendor goods, plus 34 {item:8831}, 39 {item:11137} and 208 {item:11176} to gather or buy."] = "大师级把上限从225提高到300，收费5金（经典旧世的价格；Forever的价格不在数据中）；它需要{skill:333} 200和角色35级，所以从200起任何一次造访都能学。{npc:11073}在{area:1517}副本（{zone:1418}）内教授大师级{skill:333}；要带队伍。现在学：{spell:13815}（210起）。225-300大约花2金20银的配方钱和1金70银的商人货物，外加34个{item:8831}、39个{item:11137}和208个{item:11176}，需自行采集或购买。",
	["Back to an {skill:333} trainer: {spell:7420} (from 15, 50c). Also learn {spell:1230643} (1s): Forever's {skill:333} camp item, 1 {item:4470} and 1 {item:10940}, placed at a campsite beside a campfire for its buff. The Camping 101: {skill:333} quest from your starting area's camping guide (after The Great Outdoors) sends you to an enchanting trainer who teaches it free."] = "回到{skill:333}训练师处：{spell:7420}（15起，50铜）。同时学习{spell:1230643}（1银）：这是Forever的{skill:333}露营物品，需1个{item:4470}和1个{item:10940}，放在营火旁的营地以获得增益。“露营入门：{skill:333}”任务来自你新手地区的露营指南（在“户外活动”之后），会派你去一位免费教它的附魔训练师那里。",
	["Back to an {skill:333} trainer: {spell:7795} (from 100) and {spell:13501} (from 130)."] = "回到{skill:333}训练师处：{spell:7795}（100起）和{spell:13501}（130起）。",
	["Buy the whole bracket's share in one go: 1 {item:6217} (1s 24c) and 32 {item:247786} (3s 20c); about 4s 44c in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1286} and {npc:1318}; {zone:1454}: {npc:3367}, {npc:3346} and {npc:5817})."] = "一次买齐这一段所需的全部：1个{item:6217}（1银24铜）和32个{item:247786}（3银20铜）；总共约4银44铜。箭头会指向本阵营最近的卖家（{zone:1453}：{npc:1286}和{npc:1318}；{zone:1454}：{npc:3367}、{npc:3346}和{npc:5817}）。",
	["Buy the whole bracket's share in one go: 34 {item:8925} (1g 70s); about 1g 70s in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1286}, Eldraeith and {npc:1325}; {zone:1454}: {npc:3367}, {npc:3348} and {npc:3334})."] = "一次买齐这一段所需的全部：34个{item:8925}（1金70银）；总共约1金70银。箭头会指向本阵营最近的卖家（{zone:1453}：{npc:1286}、Eldraeith和{npc:1325}；{zone:1454}：{npc:3367}、{npc:3348}和{npc:3334}）。",
	["Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs {skill:333} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:11072} ({zone:1429}); Horde {npc:11074} ({zone:1442}). The arrow picks the nearest of your faction. Learn now: {spell:13628} (from 150). 150-225 takes 1 {item:5500}, 1 {item:7971}, 1 {item:11082}, 71 {item:11083}, 1 {item:11128}, 1 {item:11135}, 21 {item:11137} and 1 {item:11144} to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach {spell:13637} (from 160), {item:11145} (from 200) and {spell:13746} (from 205), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3."] = "高级把上限从150提高到225，收费50银（经典旧世的价格；Forever的价格不在数据中）；它需要{skill:333} 125和角色20级，所以从125起任何一次造访都能学。只有少数训练师教：联盟{npc:11072}（{zone:1429}）；部落{npc:11074}（{zone:1442}）。箭头会指向本阵营最近的一位。现在学：{spell:13628}（150起）。150-225需要1个{item:5500}、1个{item:7971}、1个{item:11082}、71个{item:11083}、1个{item:11128}、1个{item:11135}、21个{item:11137}和1个{item:11144}，需自行采集或购买。把这些全带在包里来（上面的步骤备齐，其余从拍卖行买）：这些训练师还教{spell:13637}（160起）、{item:11145}（200起）和{spell:13746}（205起），且制作无需工作台，所以就地制作，技能一到就学下一个配方。一趟顶三趟。",
	["Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs {skill:333} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:333} trainer teaches it: Alliance {npc:5157} ({zone:1455}), {npc:11072} ({zone:1429}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) and {npc:7949} ({zone:1444}); Horde {npc:3345} ({zone:1454}), {npc:11074} ({zone:1442}), {npc:4616} ({zone:1458}) and {npc:3011} ({zone:1456}). The arrow picks the nearest of your faction. Learn now: {spell:7771} (from 70, 2s). 75-150 takes about 2s of recipes, plus 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} and 20 {item:11083} to gather or buy."] = "中级把上限从75提高到150，收费5银（经典旧世的价格；Forever的价格不在数据中）；它需要{skill:333} 50和角色10级，所以从50起任何一次造访都能学。并非每位{skill:333}训练师都教：联盟{npc:5157}（{zone:1455}）、{npc:11072}（{zone:1429}）、{npc:1317}（{zone:1453}）、{npc:4213}（{zone:1457}）和{npc:7949}（{zone:1444}）；部落{npc:3345}（{zone:1454}）、{npc:11074}（{zone:1442}）、{npc:4616}（{zone:1458}）和{npc:3011}（{zone:1456}）。箭头会指向本阵营最近的一位。现在学：{spell:7771}（70起，2银）。75-150大约花2银的配方钱，外加1个{item:1210}、1个{item:6338}、4个{item:10938}、121个{item:10940}和20个{item:11083}，需自行采集或购买。",
	["Learn {skill:333}"] = "学习{skill:333}",
	["Still at the Expert trainer: {spell:13637} (from 160)."] = "仍在高级训练师处：{spell:13637}（160起）。",
	["Still at the Expert trainer: {spell:13702} (from 200) and {spell:13746} (from 205)."] = "仍在高级训练师处：{spell:13702}（200起）和{spell:13746}（205起）。",
	["{item:16217} teaches {spell:20017} ({skill:333} 265) for 1g 20s. Sold by Alliance: {npc:4229} ({zone:1457}), limited stock; Horde: {npc:4561} ({zone:1458}), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it."] = "{item:16217}教{spell:20017}（{skill:333} 265），售价1金20银。出售者：联盟{npc:4229}（{zone:1457}），限量；部落{npc:4561}（{zone:1458}），限量。卖家每次只备一两个，售出后过段时间补货；它拾取即绑定，所以拍卖行永远没有。",
	["{item:20747} is orange at 253 (yellow 260, green 270, grey 280): about 34 crafts to 275. Each takes 1 {item:11176}, 1 {item:8831} and 1 {item:8925}. One {item:11176} (level 41-50 greens) and one {item:8831} (herbalists) a craft; the oil sells well. {npc:15419} sells the formula at the inn of {area:3425} ({zone:1451}): fly there, the mobs around it are level 55 and up. {item:11176} (208 for 225-300): {skill:333}: disenchant green items of item level 41-50; or the Auction House."] = "{item:20747}在253时为橙色（260黄、270绿、280灰）：大约34次制作可到275。每次需要1个{item:11176}、1个{item:8831}和1个{item:8925}。每次制作约耗一个{item:11176}（41-50级绿装）和一个{item:8831}（草药师采集）；这油很好卖。{npc:15419}在{area:3425}（{zone:1451}）的旅店出售配方：飞过去吧，周围的怪物是55级以上。{item:11176}（225-300需208个）：{skill:333}：分解物品等级41-50的绿装；或在拍卖行购买。",
