G["forever/class/warlock/orb-of-soranruk"] = {
	["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "20多级可用的稀有副手宝珠或法杖，所需碎片来自两个副本。",
	["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "可选择副手的{item:6898}或双手的{item:15109}。",
	["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "索兰鲁克碎片，来自副本内的暮光侍僧",
	["Warlock"] = "术士",
	["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236}（22-30级，五人小队）位于{area:228}南边的山丘上。救出入口右侧牢房里的囚犯，他就会打开通往庭院的路。影牙暗魂（20-21级，精英）并不在庭院里：它们走过庭院后的厅堂，沿向左弯曲的斜坡上行，进入后面的建筑。一趟大约有十二只，五分之一会掉落大块碎片，所以把每个暗魂都清掉，没掉就再刷一趟。",
	["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797}（24-32级，五人小队）的入口在{zone:1440}西北海岸的废墟中，位于{area:414}的水下。暮光侍僧（24-25级，精英，治疗者）守在最后几个厅堂，围绕{npc:4832}以及{npc:4829}前的祭坛；每只都会掉一块碎片，但一趟只刷三只，且两小时内不会刷新，所以一趟只够一个术士：先杀掉它们，别让它们治疗其他怪物。",
	["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}，来自副本内的影牙暗魂",
	["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the {area:380}. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247}与{npc:6244}一起扎营，帐篷就在{zone:1413}南部{area:378}东北不远处。联盟术士从{area:392}或塞拉摩过来；部落术士则从{area:380}向南走。他要的是两个副本里的碎片：在去{area:2797}和{area:236}之前先接任务。",
}

G["forever/class/warlock/tome-of-sacrifice"] = {
	["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "60级时，{npc:14463}在{zone:1419}西部那片满是恶魔的谷地{area:73}中等你。伤痕谷里尽是攻击凶狠的精英：先给自己绑好灵魂石，进去后贴右侧墙壁走，或者直接骑马冲过去。{npc:14463}会一次交给你两个差事。",
	["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "把两样都交给{npc:14463}，拿走{item:18601}。在{area:73}中找到独自站立的{npc:12396}（61级，精英），在约30码外让你的虚空行者拉住他，然后对他引导牢笼约20秒：他会攻击你来挣脱，而他的{spell:45}能打断引导，必要时牺牲虚空行者换取护盾。建议组队：再有一名玩家抗怪就轻松了。引导结束后他会变成{item:18605}：点击它。若引导被打断，就杀掉他或逃跑，再找下一只。",
	["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "赫达林恶魔（57-60级，精英）占据{zone:1452}最南端的{area:2256}：建议组队。两名杀戮者守着桥后的峡谷；西侧的隧道通向更多新兵，它们最好对付（小心它们的{spell:7645}）。术士可以用恐惧或{spell:710}配合持续伤害一只只单刷，但很慢。它们任何一个都可能掉赫达林之泪，五次击杀有四次。",
	["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "野生萨特（55-57级，精英）遍布{area:2577}东翼的扭木区：带上五人小队。五分之四会掉一份血液，但它们两小时内不刷新，一次全清可能凑不够十五份；重置后再刷一趟。{area:2518}的后门需要{item:18249}，它就在这一翼掉落；在有人拿到之前，从{zone:1444}中部{area:2577}的正门进入。",
	["Warlock"] = "术士",
	["{item:18601}, on a {npc:12396}"] = "{item:18601}，在{npc:12396}身上",
	["{item:18603}, from the Wildspawn inside"] = "{item:18603}，来自副本内的野生萨特",
	["{item:18605}, click it"] = "{item:18605}，点击它",
}

G["forever/collectibles/pets/flik"] = {
	["{npc:14860} sells two frogs (1g each) while the Darkmoon Faire is in town; Forever has not shown the Faire yet. In Classic it sets up south of {area:87} in {zone:1429} one month and near {zone:1456} in {zone:1412} the next; go to whichever is up. {npc:14860} runs all over the Faire grounds, so look around for him. He carries only one {item:11027} at a time and restocks it about every 30 minutes: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:14860}在暗月马戏团来访期间出售两只青蛙（每只1金）；Forever目前还没开放马戏团。经典旧世中，它一个月设在{zone:1429}的{area:87}以南，下个月设在{zone:1412}内{zone:1456}附近；哪边开放就去哪边。{npc:14860}会跑遍整个马戏团场地，所以四处找找他。他一次只带一只{item:11027}，大约每30分钟补货：他身上没有的话，就是刚被人买走了。每个宠物物品使用时都会教会对应的小伙伴；之后目标仍保持勾选。",
}

G["forever/collectibles/pets/green-wing-macaw"] = {
	["Defias Pirates, on the ship"] = "迪菲亚海盗，在船上",
	["{area:1581} is a group of five at level 17-26, under {area:20}: go in at the {area:20} mine and follow the tunnel down to the instance portal. The Defias Pirates (elite, level 19-20) on and around the ship at the far end drop the macaw about once in 30 kills, so plan on several runs; a character well past the dungeon's level clears it alone. The cage can be traded: look at the Auction House too."] = "{area:1581}是17-26级的五人副本，位于{area:20}地下：从{area:20}的矿洞进入，沿隧道走到副本传送门。最深处船上及其周围的迪菲亚海盗（精英，19-20级）约每30次击杀掉落一次鹦鹉，所以要做好刷几趟的准备；等级远超该副本的角色可以单刷。笼子可以交易：也去拍卖行看看。",
	["{area:1581} portal, at the bottom of the mine"] = "{area:1581}传送门，在矿洞底部",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞内",
}

G["forever/collectibles/pets/tiny-crimson-whelpling"] = {
	["The red whelps live in the hills of the eastern {zone:1437}, towards {area:1037}: about 50 of them, back about five minutes after a kill in Classic's data. Red Whelps (levels 23-24) and Crimson Whelps (25-26) drop the whelpling about once in 650 kills, the Flamesnorting Whelps (26-27) mixed in with them only once in 1,600, so expect a long farm. It can be traded, so the Auction House may be quicker."] = "红色幼龙栖息在{zone:1437}东部的丘陵，靠近{area:1037}：大约50只，按经典旧世的数据，击杀后约五分钟刷新。红色幼龙（23-24级）和赤色幼龙（25-26级）约每650次击杀掉落一次幼龙宠物，混在其中的喷火幼龙（26-27级）掉率仅为1,600分之一，所以做好长期刷的准备。它可以交易，所以拍卖行可能更快。",
}

G["forever/exploration/eastern-kingdoms-45-60"] = {
	["9 areas to discover here, levels 46-63."] = "本段有9个区域可探索，等级46-63。",
	["Cross {area:254} from the south of the {zone:1427} into the {zone:1428}: stay on the chain path inside, past the dungeon entrances. {area:2418} (Alliance) is in the east."] = "从{zone:1427}南部穿过{area:254}进入{zone:1428}：进去后沿锁链通道走，经过各副本入口。{area:2418}（联盟）在东部。",
	["Fly to {area:144} and ride south through {zone:1432} into the {zone:1418}, then west to {area:340} (Horde guards)."] = "飞到{area:144}，向南骑过{zone:1432}进入{zone:1418}，然后向西到{area:340}（部落守卫）。",
	["Fly to {area:272} and ride north through the {zone:1416} into southern {zone:1422}, or go east from {zone:1420} past {area:813}."] = "飞到{area:272}，向北骑过{zone:1416}进入{zone:1422}南部；或从{zone:1420}向东经过{area:813}。",
	["Fly to {area:3197} if you have it; otherwise fly to {area:271} and ride north through the {zone:1416} to {area:3197} in southern {zone:1422}."] = "如果你已开通{area:3197}的飞行点就直飞；否则飞到{area:271}，向北骑过{zone:1416}到{zone:1422}南部的{area:3197}。",
	["Fly to {area:340} in the {zone:1418}."] = "飞到{zone:1418}的{area:340}。",
	["Ride east out of {zone:1430} into the {zone:1435} and take the road south into the {zone:1419}; {area:1438} (Alliance) stands just inside."] = "从{zone:1430}向东骑出，进入{zone:1435}，再沿路向南进入{zone:1419}；{area:1438}（联盟）就在入口内侧。",
	["Starts in the {zone:1425}, north-east of {zone:1424}. The last area of this guide completes the {zone:1415} map. 14 areas to discover here, levels 41-49."] = "从{zone:1424}东北的{zone:1425}开始。本指南的最后一个区域会补全{zone:1415}地图。本段有14个区域可探索，等级41-49。",
	["Take the pass south from the {zone:1428} into the {zone:1433}, follow the road south-west through {area:1002} into {zone:1431} and east past {area:42} into {zone:1430}."] = "从{zone:1428}沿隘口向南进入{zone:1433}，沿路向西南穿过{area:1002}进入{zone:1431}，再向东经过{area:42}进入{zone:1430}。",
	["The way in on foot is from the western {zone:1418}: the path by {area:340} climbs west into the {zone:1427}."] = "步行进入的路线在{zone:1418}西部：{area:340}旁的小径向西爬升，进入{zone:1427}。",
	["{zone:1419} (1/2)"] = "{zone:1419}（1/2）",
	["{zone:1419} (2/2)"] = "{zone:1419}（2/2）",
	["{zone:1422} (1/2)"] = "{zone:1422}（1/2）",
	["{zone:1422} (2/2)"] = "{zone:1422}（2/2）",
	["{zone:1423} (1/3)"] = "{zone:1423}（1/3）",
	["{zone:1423} (2/3)"] = "{zone:1423}（2/3）",
	["{zone:1423} (3/3)"] = "{zone:1423}（3/3）",
	["{zone:1425} (1/2)"] = "{zone:1425}（1/2）",
	["{zone:1425} (2/2)"] = "{zone:1425}（2/2）",
