G["forever/reputation/thorium-brotherhood"] = {
	["10 {item:11370}: 50"] = "10个{item:11370}：50",
	["2 {item:17012}: 150"] = "2个{item:17012}：150",
	["Back to {area:1446}"] = "回到{area:1446}",
	["Belt, 20 Thorium Bars"] = "腰带，20个瑟银锭",
	["Blacksmiths with 265 skill can buy their way up with Thorium Bars: {npc:14567} in {area:976} trades the Imperial Plate plans for bars, and each pays Brotherhood reputation. {quest:7652} opens them (100). Belt 20 bars (100), Bracer 20 (100), Shoulders 20 (100), Boots 40 (150), Helm 50 (200), Chest 60 (200), Leggings 60 (200): 1,150 reputation for 270 Thorium Bars. They count at any standing, so do them before Burninate's turn-ins."] = "锻造技能265的玩家可以用瑟银锭买声望：{area:976}的{npc:14567}用锭换取帝王板甲图纸，每件都给兄弟会声望。{quest:7652}会开启这些图纸（给100点）。腰带20锭（100）、护腕20（100）、护肩20（100）、靴子40（150）、头盔50（200）、胸甲60（200）、护腿60（200）：270个瑟银锭换1,150点声望。它们在任何声望等级都计数，所以在Burninate的上交之前先做这些。",
	["Boots, 40 Thorium Bars"] = "靴子，40个瑟银锭",
	["Bracer, 20 Thorium Bars"] = "护腕，20个瑟银锭",
	["Carry a {item:17203} ({npc:11988}, the {area:2717}) to {npc:12944} and he offers you a contract: ask about the offer and take it. Handing in the contract with the ingot pays 200 reputation and {item:18592}, the hammer Blacksmiths later join with the {item:17204} into {item:17182}."] = "把{item:17203}（来自{area:2717}的{npc:11988}）带给{npc:12944}，他会给你一份契约：询问这个提议并接受它。把契约连同锭交上，可得200点声望和{item:18592}；这把锤子之后会被锻造师与{item:17204}合成{item:17182}。",
	["Chest, 60 Thorium Bars"] = "胸甲，60个瑟银锭",
	["Coal, 1 per turn-in"] = "煤，每次上交1块",
	["Dark Iron Slaver"] = "黑铁奴隶贩子",
	["Dark Iron Taskmaster"] = "黑铁监工",
	["Friendly to Honored is 6,000 reputation. While you are Friendly Burninate takes {quest:7737} instead: 25 reputation for 4 {item:18945}, 240 turn-ins and 960 residue in all. About a third of the {object:147516} dwarves in {area:1584} drop residue, sometimes several at once; it also sells on the Auction House. {item:11370} or {area:2717} materials at {npc:12944} (next steps) count here too. {npc:12944}'s shop opens at Friendly: {item:16979} 8g, {item:16982} 15g, {item:16983} 16g, {item:17014} 7g, {item:273572} 3g, Transmute Elemental Fire 12g."] = "从友善到尊敬是6,000点声望。友善期间Burninate改收{quest:7737}：4个{item:18945}换25点，共需240次上交、960份残渣。{area:1584}中约三分之一的{object:147516}矮人掉落残渣，有时一次掉好几份；拍卖行也有卖。在{npc:12944}处上交{item:11370}或{area:2717}材料（见后续步骤）也计入这里。{npc:12944}的商店在友善时开放：{item:16979} 8金、{item:16982} 15金、{item:16983} 16金、{item:17014} 7金、{item:273572} 3金，以及“转化元素之火”12金。",
	["Golems and {object:147516} dwarves"] = "傀儡和{object:147516}矮人",
	["Greater Lava Spider"] = "巨型熔岩蜘蛛",
	["Greater Lava Spiders"] = "巨型熔岩蜘蛛",
	["Heavy War Golem"] = "重型战争傀儡",
	["Heavy War Golems and the Dark Iron Taskmasters and Slavers work all over the floor of the Cauldron below {area:1446}. The {item:18959} drops from Dark Iron Steamsmiths at the furnaces in the middle, the {item:18960} from Dark Iron Lookouts on the southern ridges: about one in ten of each."] = "重型战争傀儡以及黑铁监工和奴隶贩子在{area:1446}下方的火山口地面上四处活动。{item:18959}由中部熔炉处的黑铁蒸汽铁匠掉落，{item:18960}由南部山脊上的黑铁瞭望员掉落：各约十分之一。",
	["Helm, 50 Thorium Bars"] = "头盔，50个瑟银锭",
	["Honored to Revered is 12,000 reputation, all of it from {npc:12944} in the Grim Guzzler, the tavern deep in {area:1584}. The way there: with the {item:11000}, open the East Garrison door near the entrance; without it, win the Ring of Law and climb to the East Garrison. Pull the {object:161460} there to lower the bridge to the Manufactory, the only way to the Guzzler. His Favor Amongst the Brotherhood turn-ins never stop counting: 1 {item:17010}, 1 {item:17011} or 1 {item:11382} for 200, 2 {item:17012} for 150, 10 {item:11370} for 50. To Revered that is 60 cores, 160 {item:17012} or 2,400 {item:11370}. The cores and the leather come only from the {area:2717}, which is not among the first raids Blizzard has announced for Forever; until it opens, {item:11370} is the way. Miners with 230 skill find Dark Iron Deposits around the Cauldron in {zone:1427}, across the {zone:1428} and inside {area:1584}, and a deposit now and then gives a {item:11382}; the ore also sells on the Auction House. Honored opens {item:16980} 18g, {item:19156} 6g, {item:19149} 6g, {item:16984} 16g, {item:16989} 9g, {item:19148} 6g, {item:17015} 22g, {item:17016} 22g and {item:273576} 8g."] = "从尊敬到崇敬是12,000点声望，全部来自{area:1584}深处那间酒馆里的{npc:12944}。去那里的办法：带着{item:11000}，可从入口附近的东营区大门进去；没有它，就先赢下“法律之环”，再爬到东营区。拉动那里的{object:161460}放下通往制造厂的桥，这是去那间酒馆的唯一路径。他的“兄弟会的恩惠”上交始终计数：1个{item:17010}、1个{item:17011}或1个{item:11382}换200点，2个{item:17012}换150点，10个{item:11370}换50点。到崇敬需要60个核心、160个{item:17012}或2,400个{item:11370}。核心和皮革只来自{area:2717}，而它不在暴雪公布的Forever首批团队副本中；在它开放前，只能靠{item:11370}。230技能的矿工能在{zone:1427}的火山口周围、{zone:1428}那边以及{area:1584}内找到黑铁矿脉，偶尔一条矿脉会给一个{item:11382}；矿石在拍卖行也有卖。尊敬时开放：{item:16980} 18金、{item:19156} 6金、{item:19149} 6金、{item:16984} 16金、{item:16989} 9金、{item:19148} 6金、{item:17015} 22金、{item:17016} 22金和{item:273576} 8金。",
	["Imperial Plate, for Blacksmiths"] = "帝王板甲，供锻造师",
	["Incendosaur"] = "炎蜥",
	["Leggings, 60 Thorium Bars"] = "护腿，60个瑟银锭",
	["Neutral to Friendly is 3,000 reputation. Burninate takes Restoring Fiery Flux Supplies only while you are Neutral: 25 reputation for 2 Incendosaur Scales, 1 Coal and either 4 Iron Bars, 4 {item:3356} or 10 {item:4234}. These are level 60 quests, so they always pay in full. After the 700 from the {area:1446} quests that is 92 turn-ins: 184 scales (about 60 Incendosaurs), 92 Coal (Burninate sells it at 5 silver: 4g 60s) and 368 Iron Bars, 368 {item:3356} or 920 {item:4234}. If those quests paid you only 140 at 60, it is 115 turn-ins: 230 scales, 115 Coal (5g 75s) and 460 bars or {item:3356} or 1,150 {item:4234}. Miners smelt the bars from {item:2772}, herbalists pick {item:3356}, skinners get {item:4234} from beasts of level 28 to 40; all three sell on the Auction House. Pick whichever is cheapest for you, or mix them. Blacksmiths who did the Imperial Plate quests need 46 fewer turn-ins."] = "从中立到友善是3,000点声望。Burninate只在你处于中立时收“恢复炽热助熔剂补给”：2块炎蜥鳞片、1块煤，外加4个铁锭、4个{item:3356}或10个{item:4234}，换25点声望。这些是60级任务，所以总是全额给声望。扣除{area:1446}任务给的700点后，还需92次上交：184块鳞片（约60只炎蜥）、92块煤（Burninate按5银出售：4金60银），以及368个铁锭、368个{item:3356}或920个{item:4234}。如果那些任务在60级只给了你140点，则需115次上交：230块鳞片、115块煤（5金75银）和460个铁锭或{item:3356}，或1,150个{item:4234}。矿工用{item:2772}熔炼铁锭，草药师采集{item:3356}，剥皮者从28-40级的野兽身上获得{item:4234}；三者在拍卖行都有卖。挑对你最便宜的一种，或者混着用。做过帝王板甲任务的锻造师可少交46次。",
	["Only if you take the {item:4234} turn-in below and skin it yourself: the wyverns, basilisks and scorpids here (level 28 to 40) yield it. Ten per turn-in."] = "只有当你选择下面用{item:4234}上交并自己剥皮时：这里的双足飞龙、蜥蜴和蝎子（28-40级）都能剥出。每次上交十块。",
	["Only if you take the {item:4234} turn-in below and skin it yourself: the yetis and mountain lions here (level 28 to 40) yield it. Ten per turn-in."] = "只有当你选择下面用{item:4234}上交并自己剥皮时：这里的雪人和山狮（28-40级）都能剥出。每次上交十块。",
	["Optional, and it saves every later trip to {npc:12944} the Ring of Law fight. {npc:8888} is a ghost in the middle of {area:1445}: only the dead see him, so die in the mountain and walk to his tomb as a spirit. He sends you after {npc:9056} in {area:1584}, who always drops {item:10999}; place it on {npc:8888}'s monument in the Shrine of Thaurissan and the {item:11000} falls out. {area:1584} is a five-player dungeon: group up."] = "可选，但能省掉以后每次去{npc:12944}时的“法律之环”战斗。{npc:8888}是{area:1445}中央的幽灵：只有死者才能看见他，所以在山里死掉，以灵魂状态走到他的墓前。他会派你去{area:1584}找{npc:9056}，后者必定掉落{item:10999}；把它放到索瑞森神殿里{npc:8888}的纪念碑上，{item:11000}就会掉出来。{area:1584}是五人副本：请组队。",
	["Reputation · Raids and dungeons"] = "声望 · 团队副本与地下城",
	["Revered to Exalted is 21,000 more: 105 cores or Bloods, 280 {item:17012} or 4,200 {item:11370}. The {area:2717} materials come from the raid, so a guild or the auction house does most of the work. Revered opens {item:19165} 9g, {item:19157} 9g, {item:19162} 9g, {item:19163} 9g, {item:17013} 18g, {item:19164} 8g, {item:16988} 20g, {item:19166} 7g, Blackfury 7g and {item:273577} 10g. Exalted opens the epic weapon plans {item:19170}, Blackguard and Nightfall (12g each) and {item:20039} 8g."] = "从崇敬到崇拜还要21,000点：105个核心或血液、280个{item:17012}或4,200个{item:11370}。{area:2717}的材料来自团队副本，所以大部分工作要靠公会或拍卖行。崇敬时开放：{item:19165} 9金、{item:19157} 9金、{item:19162} 9金、{item:19163} 9金、{item:17013} 18金、{item:19164} 8金、{item:16988} 20金、{item:19166} 7金、“黑怒”7金和{item:273577} 10金。崇拜时开放史诗武器图纸{item:19170}、“黑卫”和“夜幕”（各12金），以及{item:20039} 8金。",
	["Shoulders, 20 Thorium Bars"] = "护肩，20个瑟银锭",
	["The spiders roam the lava pools and plateaus of the south-west."] = "蜘蛛在西南的熔岩池和高地上出没。",
	["The {item:11000}"] = "{item:11000}",
	["The {object:179827} board"] = "{object:179827}告示板",
	["via Iron: 4 Iron Bars"] = "走铁锭路线：4个铁锭",
	["via {item:3356}: 4 {item:3356}"] = "走{item:3356}路线：4个{item:3356}",
	["via {item:4234}: 10 {item:4234}"] = "走{item:4234}路线：10个{item:4234}",
	["{area:1443} is the cave in the north of the Cauldron. The {item:18922} lie on a bench on its upper ledge, beside {npc:14621}: a level 50 elite with guards, easy at 60, worth a group below 55. Incendosaurs swim in the lava pools inside and around the north rim; every one drops two to four Incendosaur Scales. Keep every scale: Burninate's turn-ins take two each. If you find {npc:14636}'s ornate pillow in the dwarves' sleeping quarters, take it to {npc:14628} at {area:1446} for 100 more."] = "{area:1443}是火山口北部的洞穴。{item:18922}放在上层岩台的一张长凳上，旁边是{npc:14621}：一个带着守卫的50级精英，60级时轻松，55级以下值得组队。炎蜥在洞内和北缘周围的熔岩池里游动；每只都掉两到四块炎蜥鳞片。把每块鳞片都留着：Burninate每次上交要两块。如果你在矮人的睡房里找到{npc:14636}的华丽枕头，把它带给{area:1446}的{npc:14628}，还能多得100点。",
	["{area:1446} is the scaffolded camp on the north-west rim of the Cauldron, with a flight point. Everyone starts Neutral with the Brotherhood. These seven quests (level 48 to 50) pay 100 reputation each: 700 in all, 800 with the pillow below. In Classic a quest pays less once it is 6 or more levels below you, only 20 each at 60, so do them while you level through {zone:1427} if you can; your first turn-in shows which. {npc:14624}'s {quest:7722} also opens his {item:18942} turn-ins, so it is needed at any level. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%."] = "{area:1446}是火山口西北缘搭着脚手架的营地，设有飞行点。所有人一开始与兄弟会都是中立。这七个任务（48到50级）各给100点声望：共700点，加上下面提到的枕头为800点。在经典旧世中，任务比你低6级或更多时给的声望会减少，60级时每个只有20点，所以若能，就在练级穿过{zone:1427}时做；你第一次上交就能看出实际给多少。{npc:14624}的{quest:7722}还会开启他的{item:18942}上交，所以任何等级都需要做它。本篇攻略的数字未计入传承特长“外交家”，它最多加10%。",
	["{item:10999}, {npc:9056} inside {area:1584}"] = "{item:10999}，{area:1584}内的{npc:9056}",
	["{item:11370}: Dark Iron Deposits, {skill:186} 230"] = "{item:11370}：黑铁矿脉，{skill:186} 230",
	["{item:11382}: 200"] = "{item:11382}：200",
	["{item:11382}: Molten Destroyers, sometimes a {object:165658}"] = "{item:11382}：熔火摧毁者，偶尔来自{object:165658}",
	["{item:17010}: 200"] = "{item:17010}：200",
	["{item:17010}: Firewalkers, Flameguards and Firelords in the {area:2717}"] = "{item:17010}：{area:2717}的火焰行者、烈焰守卫和火焰领主",
	["{item:17011}: 200"] = "{item:17011}：200",
	["{item:17011}: Lava Elementals, Lava Reavers and Molten Destroyers"] = "{item:17011}：熔岩元素、熔岩掠夺者和熔火摧毁者",
	["{item:17012}: skin Ancient Core Hounds and Magmadar"] = "{item:17012}：剥取上古熔火犬和玛格曼达",
	["{item:17203}, already in your bags"] = "{item:17203}，已在你的包里",
	["{item:18628}, from {npc:12944}"] = "{item:18628}，来自{npc:12944}",
	["{item:18942} to Friendly"] = "{item:18942} 到友善",
	["{item:18944}, 2 per turn-in"] = "{item:18944}，每次上交2个",
	["{item:18945}, 4 per turn-in"] = "{item:18945}，每次上交4个",
	["{item:18946}, elite: group up below 55"] = "{item:18946}，精英：55级以下组队",
	["{item:18950}, if you find it"] = "{item:18950}，如果你找得到",
