G["forever/class/druid/aquatic-form"] = {
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards {npc:11800}, in the middle of {area:2361}, flies druids straight to {area:702}."] = "施放{spell:18960}。把两半都放在背包里，站在西北岸的{area:2362}旁，使用{item:15883}把它们拼合，然后再次施放{spell:18960}（在{zone:1450}内有效）降落到{npc:11802}身旁。他在自己那栋楼的楼上：从里面上楼，箭头分不清楼层。之后，{area:2361}中央的{npc:11800}会把德鲁伊直接送到{area:702}。",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:11798} flies druids to {area:1638}."] = "施放{spell:18960}。把两半都放在背包里，站在西北岸的{area:2362}旁，使用{item:15883}把它们拼合，然后再次施放{spell:18960}（在{zone:1450}内有效）降落到{npc:11802}身旁。他在自己那栋楼的楼上：从里面上楼，箭头分不清楼层。{npc:11798}会把德鲁伊送到{area:1638}。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. {quest:28} runs on a 30-minute timer. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。{quest:28}每30分钟计时刷新。{area:2361}下方的{area:656}深处底部有六个饰物容器（花瓶），藏在狭窄的凹坑里，常在冒泡的裂隙附近（湖中央的{object:177524}能补满呼吸）；每个打开后三分钟刷新，其他德鲁伊也会来拿。浮上水面前确认背包里有{item:15877}：拾取后五分钟它就会消失。直接把它游送到西北岸的{area:2362}，在神龛范围内使用，并与树旁的{npc:11799}交谈。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. {quest:29} runs on a 30-minute timer. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。{quest:29}每30分钟计时刷新。{area:2361}下方的{area:656}深处底部有六个饰物容器（花瓶），藏在狭窄的凹坑里，常在冒泡的裂隙附近（湖中央的{object:177524}能补满呼吸）；每个打开后三分钟刷新，其他德鲁伊也会来拿。浮上水面前确认背包里有{item:15877}：拾取后五分钟它就会消失。直接把它游送到西北岸的{area:2362}，在神龛范围内使用，并与树旁的{npc:11799}交谈。",
	["Druid"] = "德鲁伊",
	["Fly from {area:2361} to {area:442}. The {object:177792} lies far out on the sea floor off the north coast, between tall rocks west of where the {area:456} reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water."] = "从{area:2361}飞往{area:442}。{object:177792}在北部海岸外的远海海底，位于{area:456}入海处以西的高耸岩石之间：从岩石东侧看不到它。注意呼吸和黑海岸长尾鲨；在水面上战斗。",
	["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Head west to the coast: the {object:177790} lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue."] = "从{area:442}乘船到{zone:1453}，再飞往{area:108}。向西走到海岸：{object:177790}在远海海底、一处冒泡的裂隙（能补呼吸）旁，位置在一只沉没的锚以西。这里有鲨鱼游荡；不要越过残骸继续往前游，深水会带来疲劳。",
	["Take the portal up to {npc:4217} in the {area:1658}. {quest:5061}: swim fast and breathe underwater."] = "乘传送门上去找{area:1658}里的{npc:4217}。{quest:5061}：游得快些，并在水下呼吸。",
	["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies at the bottom of very deep water off the coast north-west of the {area:228}, beside an air fissure where you can breathe: watch your breath on the way down."] = "乘{npc:11798}的航班到{zone:1456}，飞往{zone:1454}，再乘飞艇到{zone:1420}；{zone:1421}在{zone:1458}以南。{object:177790}在{area:228}西北海岸外的极深水底，紧挨着一处能呼吸的空气裂隙：下潜途中注意呼吸。",
	["The {object:177792} lies underwater in the {area:382} pond north of the {area:380}, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."] = "{object:177792}在{area:380}以北{area:382}池塘的水下，一堵木墙前。那里的风险投资公司成员很容易加入战斗：从西边进入以避开大部分。",
	["{item:15882}, from the {object:177790}"] = "{item:15882}，来自{object:177790}",
	["{item:15883}, from the {object:177792}"] = "{item:15883}，来自{object:177792}",
	["{npc:3033} stands in the druids' hut on {area:1639}."] = "{npc:3033}站在{area:1639}的德鲁伊小屋中。",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. Skyborne: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up."] = "{npc:4217}站在{area:1658}德鲁伊建筑的楼上。天裔：施放{spell:18960}，在{area:2361}中央乘{npc:11800}的航班（她把德鲁伊送到{area:702}，无需飞行路线），然后乘传送门上去。",
}

G["forever/class/druid/cure-poison"] = {
	["Back in {area:442}, at the north end of the village."] = "回到{area:442}，在村子北端。",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}去见{npc:11802}，然后乘{npc:11798}的航班到{area:1638}。{npc:11802}在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}去见{npc:11802}，然后在{area:2361}中央乘{npc:11800}的航班（她把德鲁伊送到{area:702}，无需飞行路线），再乘传送门上去到{zone:1457}。{npc:11802}在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。他会给你{item:15842}。{npc:11798}会把德鲁伊送到{area:1638}；从那里再飞往{area:380}。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15844}. Then fly to {area:442} (learn the {zone:1450} flight path at Sindrayl first if you have not)."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。他会给你{item:15844}。然后飞往{area:442}（如果还没学过{zone:1450}的飞行路线，先在Sindrayl那里学习）。",
	["Druid"] = "德鲁伊",
	["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the {area:380}. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "每只{npc:3234}（14-15级）都会掉一只角，但它们数量稀少且四处游荡：到{area:382}附近的极北地带和各处绿洲寻找，尤其是{area:380}东南的{area:388}。它们会远程冲锋并践踏。草药师能在{zone:1413}北部各处采到{item:2449}。",
	["From the {area:380} head north to {area:384} and climb to the bubbling {object:19464} on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the {item:15842}: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run."] = "从{area:380}向北到{area:384}，爬上山顶冒泡的{object:19464}。燃烧之刃教徒在周围扎营：一次拉一两个。站在水里使用{item:15842}：三个燃烧之刃毒理学家（13-14级，会诅咒和术士法术）出现并攻击。不必杀掉他们：采样器一满就跑。",
	["He hands you the {item:15826}: ten doses, one per gazelle."] = "他会给你{item:15826}：十剂，每只瞪羚用一剂。",
	["Head north-east from {area:442} to {area:445}. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the {item:15844} (not the {item:12350} of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight."] = "从{area:442}向东北到{area:445}。站在瀑布顶端的洞口，而不是下面的河里，使用{item:15844}（不是另一个任务的{item:12350}）。纳迦沿攀爬路线分布，对岸有一名施法者，灌满采样器还会召来两个（一名逐浪者和一名毒理学家，15级）：先清路，并做好战斗准备。",
	["She hands you the {item:15826}: ten doses, one per deer. Destroy any leftover {item:15851}."] = "她会给你{item:15826}：十剂，每只鹿用一剂。销毁剩余的{item:15851}。",
	["Sickly Deer"] = "病弱鹿",
	["Sickly Gazelle"] = "病弱的瞪羚",
	["The Lunar Fungal Blooms are tiny white-spotted mushrooms on the floors and walls of the small moonkin caves in the hills just east and south-east of {area:442}; each gives one or two fungus, and each cave holds only a few, so go from cave to cave (they regrow in three minutes). The moonkin there are irritable. No {skill:182} needed for the blooms. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it ({npc:1313} or {npc:1302} in {zone:1453}, or the Auction House)."] = "月光菌花是{area:442}正东和东南丘陵里小型枭兽洞穴地面和墙上的白色斑点小蘑菇；每朵给一两个菌，而每个洞穴只有几朵，所以要一个洞一个洞地走（三分钟重生）。那里的枭兽脾气暴躁。采月光菌花不需要{skill:182}。{item:2449}则需要{skill:182}：草药师能在{zone:1439}各处采到，其他人只能购买（{zone:1453}的{npc:1313}或{npc:1302}，或者拍卖行）。",
	["Use the {item:15826} on Sickly Gazelles"] = "对病弱的瞪羚使用{item:15826}",
	["Use the {item:15826} on living Sickly Gazelles (level 3): they graze on both sides of the road north of the {area:380} up to the {zone:1440} border, north-west of the {area:380} and west of {area:392}. Druid trick: root a gazelle with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from {npc:3448} for a fresh salve."] = "对活着的病弱瞪羚（3级）使用{item:15826}：它们在{area:380}以北、直到{zone:1440}边界的道路两侧吃草，也在{area:380}西北和{area:392}以西活动。德鲁伊小技巧：用{spell:339}缠住一只瞪羚，在缠绕生效前涂上药膏，缠绕造成的击杀会再计一次，所以五只瞪羚就够。浪费了一剂？放弃任务，从{npc:3448}重新接取，就能拿到新的药膏。",
	["Use the {item:15826} on living {npc:12298} (level 5, a green cloud over them): they roam {zone:1439} from the {area:456} to the {zone:1440} border, many around the Blackwood furbolg camp north-east of {area:442}. Druid trick: root a deer with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from {npc:3702} for a fresh salve."] = "对活着的{npc:12298}（5级，头顶有绿色云雾）使用{item:15826}：它们在{zone:1439}从{area:456}到{zone:1440}边界一带游荡，{area:442}东北的黑木熊怪营地周围尤其多。德鲁伊小技巧：用{spell:339}缠住一只鹿，在缠绕生效前涂上药膏，缠绕造成的击杀会再计一次。在某只不计数的鹿身上浪费了一剂？放弃任务，从{npc:3702}重新接取，就能拿到新的药膏。",
	["Use the {item:15826} on {npc:12298}"] = "对{npc:12298}使用{item:15826}",
	["{item:15842}, standing in the pool"] = "{item:15842}，站在水池中",
	["{item:15844}, at the cave mouth"] = "{item:15844}，在洞口",
	["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{area:1639}的{npc:3033}会教你{spell:8946}。",
	["{npc:3033} stands in the druids' hut on {area:1639}; {npc:262560}, the Skyborne druid trainer where the airship from Zephras Isle lands in northern {zone:1412}, gives the same quest. No {skill:182}? {npc:3490} at the {area:380} sells {item:2449} later, or buy five on the Auction House now."] = "{npc:3033}站在{area:1639}的德鲁伊小屋中；{npc:262560}是泽弗拉斯岛飞艇在{zone:1412}北部降落处的天裔德鲁伊训练师，也会给同样的任务。没有{skill:182}？{area:380}的{npc:3490}以后会卖{item:2449}，或者现在就在拍卖行买五个。",
	["{npc:3033}, or {npc:262560} in northern {zone:1412}"] = "{npc:3033}，或{zone:1412}北部的{npc:262560}",
	["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448}站在{area:380}。没有{skill:182}？几步之外、驭风者训练师旁的{npc:3490}以每朵80铜出售{item:2449}，每次限购三个，直到他补货。",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217}站在{area:1658}德鲁伊建筑的楼上。没有{skill:182}？先在拍卖行买五个{item:2449}：你后面会用到。",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}; {npc:270459} by the Skyborne Portal does not give this quest. Cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217}站在{area:1658}德鲁伊建筑的楼上；天裔传送门旁的{npc:270459}不给这个任务。施放{spell:18960}，在{area:2361}中央乘{npc:11800}的航班（她把德鲁伊送到{area:702}，无需飞行路线），然后乘传送门上去。没有{skill:182}？先在拍卖行买五个{item:2449}：你后面会用到。",
	["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{area:1658}楼上的{npc:4217}会教你{spell:8946}。",
}

G["forever/class/mage/polymorph-pig"] = {
	["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "{spell:118}的新外观：它会把目标变成猪，而不是羊。",
	["Back to the {area:1221}, full of Spitelash naga. Cast your sheep {spell:118} (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with {spell:122} and {spell:1449}. Fifty clones are needed, so it takes a while; not in a raid group."] = "回到{area:1221}，那里满是怒鳞纳迦。对一名纳迦施放你的变羊术{spell:118}（变龟的那个没有用），等几秒：它会分裂成两到六个约150点生命值的变形术克隆体，并很快跑开。站在羊旁边，克隆体一出现就用{spell:122}和{spell:1449}打它们。需要五十个克隆体，所以要花些时间；不要在团队中做。",
	["Back to {npc:8395} and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags."] = "回到{npc:8395}处，再上塔。Xylem会在下一个任务中把龟壳还给你：把它留在背包里。",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower."] = "飞往{area:3137}（联盟）或{area:1237}（部落）。{npc:8395}在{npc:8379}的高塔下方扎营，位于{area:1237}以东不远处：从{area:1221}处{zone:1447}主路的岔口一路向北走到悬崖。下坐骑，他会把你传送上去；一条小径向上通往塔顶的大法师。",
	["Mage"] = "法师",
	["Polymorph Clone"] = "变形术克隆体",
	["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}：{spell:118}（猪）",
	["{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine."] = "{npc:8408}（55级，非精英，会打击和{spell:99}）躲在{area:1221}中部最大建筑{area:1223}里的怒鳞守卫身后。他必掉{item:23250}，击杀后5分半刷新。先退出团队：团队不计进度，小队可以。",
}

G["forever/class/rogue/the-horn-of-xelthos"] = {
	["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "独自进入，在庭院大门使用{item:210186}。也有玩家报告，一名获释的囚犯会替你打开庭院门：如果他在开门时你死了，就保持死亡状态直到门开；你释放后门会一直开着。如果你学会了消失，带上{item:5140}，进入前检查冷却；留到潜入失败时用。在餐厅偷取姐妹身上的{item:210213}，然后在楼梯顶端右转进入的房间偷取兄弟身上的{item:210212}（20级潜行者若没学会消失，可能需要点出欺骗大师的等级才能不被发现地接近第二个目标）。在安全的地方将二者合成：这会打破潜行。先腾出一个背包格：背包满时打开箱子可能消耗钥匙却不给号角。回到庭院马厩，把合成的钥匙用在箱子上拿到号角。远离附近的精英；任务的最低等级并不保证能安全接近。",
	["Rogue"] = "潜行者",
	["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369}是银松森林南部{area:204}外一栋房子里的箱子，位于{area:236}以南。打开它并阅读C的便条：这项工作必须独自完成，不能组队。",
	["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them."] = "{npc:4086}是一名对双方阵营都友善的地精，站在石爪山脉东部{area:461}的风险投资公司成员中间，位于{area:460}东北不远处。部落飞往{area:460}；联盟飞往{area:467}。他要先拿到{item:210187}才肯交出炸药：在他周围干活的风险投资公司伐木工（18级）身上带着。",
}

G["forever/class/warlock/shard-of-the-green-flame"] = {
	["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "50级时，{npc:14469}和他的小鬼{npc:14470}在{zone:1448}中部、{area:1997}东北的一处高地上等候：从{area:1765}的桥向北走，他们位于道路东侧、经过几只泥浆怪之后。{npc:14469}会把你派给身旁的{npc:14470}，后者要你从三个地方带回三份无瑕的恶魔精华。",
	["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "回到{npc:14470}处。他会给你{item:18626}：留着它，它能唤醒地狱火{npc:14467}。",
	["Kroshius"] = "克罗修斯",
	["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "恶魔卫士哨兵（54级）在{zone:1419}南部{area:72}周围巡逻，每名都带着一只地狱猎犬。别去碰57级的拉兹利克仆从：没有自己的任务就杀不死它们。",
	["The Legashi satyrs (level 51-53) hold the Legash Encampment on {zone:1447}'s northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly."] = "雷加什萨特（51-53级）占据{zone:1447}北部海岸的雷加什营地。每种成员都有四分之三的几率掉落精华；萨特会烧法力，唤狱者会下火雨，所以逐个拉。",
	["Warlock"] = "术士",
	["{area:1763} lies just south of {area:1997}, west of the road. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763}在{area:1997}正南、道路以西。它的两个洞穴中，{area:1770}是偏北的那个，在山上更靠上的位置；另一个没有军团士兵。{area:1770}的隧道在山丘下向北延伸，加德纳尔军团士兵（55级）守在更深的厅堂里，从最初的坡道直到{npc:9516}的房间；他们会用上钩拳打近战范围内的人。四次击杀中有三次掉精华，但只会刷出约十一个：先清出进去的路，必要时等五分钟刷新。{area:1763}和{area:1770}的教徒全部敌对。",
	["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "{npc:14467}的遗骸躺在{area:1766}，即{npc:14469}以北的烧焦坑洞中：从他的营地沿路向北走，遗骸在道路稍东处。在遗骸旁使用{item:18626}，等他起身。{npc:14467}是精英（55级）：建议组队；55级以上的术士可以用恐惧和持续伤害单挑，或用奴役恶魔，但火焰法术对他无效，而且他会把你击退。你死了他会回满血；他死后三分钟会再次起身。一只精英地狱火在遗骸南边的水池巡逻：把{npc:14467}拉开。他必掉自己的核心。丢了{item:18626}？放弃任务，从{npc:14470}重新接取。",
}

G["forever/collectibles/pets/dark-whelpling"] = {
	["The Searing Whelps of the {area:511} in southern {zone:1445} (level 42-43) and the Scalding Whelps of eastern {zone:1418} (level 41-43) drop it about once in 900 kills. The waypoint is the {area:511}, where the whelps stand thickest; the {zone:1418} whelps are the same grind. The whelpling can be traded, so the Auction House may be quicker."] = "{zone:1445}南部{area:511}的灼热雏龙（42-43级）和{zone:1418}东部的灼热的雏龙（41-43级）大约每900次击杀掉落一次。路标是{area:511}，那里雏龙最密集；{zone:1418}的雏龙也是同样的刷法。这只雏龙宠物可以交易，所以拍卖行可能更快。",
}

G["forever/collectibles/pets/tallstrider-hatchling"] = {
	["The {npc:2172} is a rare level 20 tallstrider in southern {zone:1439}, near the {area:449}. Kill counts so far give her about 0.6% per kill, roughly one in 170, and in Classic she comes back only every few hours: check her spot whenever you pass, rather than camping. The hatchling binds when you loot it, so it never reaches the Auction House."] = "{npc:2172}是{zone:1439}南部{area:449}附近一只稀有的20级长尾陆行鸟。目前统计的击杀数据显示她每次约0.6%的掉落率，约每170次一次，而在经典旧世中她每隔几小时才刷新一次：路过时顺便查看她的位置，不必死守。这只幼鸟在你拾取时就会绑定，所以永远不会出现在拍卖行。",
}

G["forever/professions/cooking"] = {
	["Any {skill:185} trainer of your faction teaches Apprentice {skill:185} (character level 5, 1s); the arrow picks the nearest. Forever: every cook knows {object:29784}. Craft a {item:279981} from one {item:4470} (38c) with {item:4471} (1s 35c, kept in your bags), then place the kit to light a cooking fire anywhere; make a few in advance (one use every 5 minutes). The first kits also raise {skill:185} to about 5. The Camping 101: {skill:185} quest at your starting area's camp sends you to this trainer."] = "本阵营任意{skill:185}训练师都教学徒级{skill:185}（角色5级，1银）；箭头会指向最近的一位。Forever：每个厨师都会{object:29784}。用一个{item:4470}（38铜）加{item:4471}（1银35铜，放在背包里）制作一个{item:279981}，然后放置这套工具，就能在任何地方点燃烹饪火堆；提前做几个（每5分钟可用一次）。最初的几套工具还能把{skill:185}提升到约5点。起始区域营地的“露营入门：{skill:185}”任务会让你去找这位训练师。",
	["Expert {skill:185} raises the cap to 225; it needs skill 125 and character level 20: it is a book, {item:16072} (1g); the arrow picks its nearest seller for your faction. Buy it and read it."] = "高级{skill:185}把上限提高到225；需要技能125和角色20级：它是一本书，{item:16072}（1金）；箭头会指向本阵营最近的卖家。买下并阅读。",
	["Innkeepers and food vendors sell {item:8932}; the arrow picks the nearest."] = "旅店老板和食品商人都出售{item:8932}；箭头会指向最近的一位。",
	["Journeyman {skill:185} raises the cap to 150; it needs skill 50 and character level 10: the arrow picks the nearest {skill:185} trainer of your faction; training costs 5s."] = "中级{skill:185}把上限提高到150；需要技能50和角色10级：箭头会指向本阵营最近的{skill:185}训练师；训练费5银。",
	["The arrow picks the nearest vendor of your faction for each item. You need 240 {item:3713} (3g 84s)."] = "箭头会为每件物品指向本阵营最近的商人。你需要240个{item:3713}（3金84银）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 30 {item:2692} (12s)."] = "箭头会为每件物品指向本阵营最近的商人。你需要30个{item:2692}（12银）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 40 {item:159} (2s)."] = "箭头会为每件物品指向本阵营最近的商人。你需要40个{item:159}（2银）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 44 {item:2678} (90c)."] = "箭头会为每件物品指向本阵营最近的商人。你需要44个{item:2678}（90铜）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 45 {item:2692} (18s)."] = "箭头会为每件物品指向本阵营最近的商人。你需要45个{item:2692}（18银）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 46 {item:2692} (18s 40c)."] = "箭头会为每件物品指向本阵营最近的商人。你需要46个{item:2692}（18银40铜）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 50 {item:2678} (1s)."] = "箭头会为每件物品指向本阵营最近的商人。你需要50个{item:2678}（1银）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 52 {item:2678} (1s 10c)."] = "箭头会为每件物品指向本阵营最近的商人。你需要52个{item:2678}（1银10铜）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 52 {item:2692} (20s 80c)."] = "箭头会为每件物品指向本阵营最近的商人。你需要52个{item:2692}（20银80铜）。",
	["The arrow picks the nearest vendor of your faction for each item. You need 52 {item:4536} (2s 75c)."] = "箭头会为每件物品指向本阵营最近的商人。你需要52个{item:4536}（2银75铜）。",
	["{item:12210} (175-225)"] = "{item:12210}（175-225）",
	["{item:12210} is orange from 175 (yellow at 215, green at 235, grey at 255): about 52 crafts to 225. Cook at any fire: a town hearth or your own {object:29784}. {item:12228} costs 50s at its vendor; the arrow picks the nearest one of your faction. {zone:1417}: {npc:2810} at {area:320} (Alliance) and {npc:2821} at {area:321} (Horde) sell the recipe and {item:2692} beside the raptors. {item:17222} (any trainer from 200, 40s) is the alternative, but it takes two {item:12205} a craft and Dustwallow's spiders drop one about two kills in five."] = "{item:12210}从175起为橙色（215黄、235绿、255灰）：做到225约需52次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:12228}在商人处售价50银；箭头会指向本阵营最近的一位。{zone:1417}：{area:320}的{npc:2810}（联盟）和{area:321}的{npc:2821}（部落）在迅猛龙旁出售配方和{item:2692}。替代品是{item:17222}（200点起任何训练师可教，40银），但每次需要两个{item:12205}，而尘泥沼泽的蜘蛛约每五次击杀掉落两次。",
	["{item:12218} (225-300)"] = "{item:12218}（225-300）",
	["{item:12218} is orange from 225 (yellow at 265, green at 285, grey at 305): about 120 crafts to 300. Cook at any fire: a town hearth or your own {object:29784}. {item:16110} costs 1g 20s at its vendor; the arrow picks the nearest one of your faction. {item:12218} is orange to 265 and green from 285, yet it still carries you to 300. Fishers can finish on {item:13931} ({npc:8137}, {area:977}; yellow to 310) instead; {item:13932} needs an {item:279982} on Forever."] = "{item:12218}从225起为橙色（265黄、285绿、305灰）：做到300约需120次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:16110}在商人处售价1金20银；箭头会指向本阵营最近的一位。{item:12218}到265仍是橙色、285起转绿，但仍能一路带到300。渔夫可以改用{item:13931}收尾（{npc:8137}，{area:977}；到310仍为黄色）；{item:13932}在Forever需要一个{item:279982}。",
	["{item:5477} (50-100)"] = "{item:5477}（50-100）",
	["{item:5477} is orange from 50 (yellow at 90, green at 110, grey at 130): about 52 crafts to 100. Cook at any fire: a town hearth or your own {object:29784}. {item:5486} costs 4s 40c at its vendor; the arrow picks the nearest one of your faction."] = "{item:5477}从50起为橙色（90黄、110绿、130灰）：做到100约需52次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:5486}在商人处售价4银40铜；箭头会指向本阵营最近的一位。",
	["{item:5479} (100-130)"] = "{item:5479}（100-130）",
	["{item:5479} is orange from 100 (yellow at 140, green at 160, grey at 180): about 30 crafts to 130. Cook at any fire: a town hearth or your own {object:29784}. {item:5488} costs 4s at its vendor; the arrow picks the nearest one of your faction. {npc:3489}, the butcher beside this vendor at the {area:380}, sells {item:3735} (18s), the recipe after Expert: buy it now."] = "{item:5479}从100起为橙色（140黄、160绿、180灰）：做到130约需30次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:5488}在商人处售价4银；箭头会指向本阵营最近的一位。{area:380}这位商人旁的屠夫{npc:3489}出售{item:3735}（18银），即高级之后的配方：现在就买下。",
	["{item:5525} (50-90)"] = "{item:5525}（50-90）",
	["{item:5525} is orange from 50 (yellow at 90, green at 110, grey at 130): about 40 crafts to 90. Cook at any fire: a town hearth or your own {object:29784}. Any {skill:185} trainer teaches it from skill 50 for 1s. The same coastal crawlers drop {item:2674} for {spell:2544} next: keep it."] = "{item:5525}从50起为橙色（90黄、110绿、130灰）：做到90约需40次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。任何{skill:185}训练师都会从技能50起以1银教授它。同样的海岸爬行者还会掉落下一步{spell:2544}所需的{item:2674}：留着。",
	["{item:5525}: ingredients"] = "{item:5525}：材料",
	["{item:5525}: shopping"] = "{item:5525}：采购",
	["{item:6888} (1-50)"] = "{item:6888}（1-50）",
	["{item:6888} is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own {object:29784}. {item:6888} comes with {skill:185} (the client teaches it with the skill); {item:2678} are a cooking vendor's. The Strigid owls of {zone:1438} drop a {item:6889} more often than not, and {zone:1439}'s moonkin drop them too. Fishers can cook {item:6290} (recipe 40c) from Rut'theran's waters instead, and {npc:6286} in {area:186} gives Recipe of the Kaldorei (seven Small Spider Legs from the Webwood spiders) for {item:5472}, orange from 10 to 50."] = "{item:6888}从1起为橙色（45黄、65绿、85灰）：做到50约需50次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:6888}随{skill:185}一起学会（客户端会随技能教授）；{item:2678}则向烹饪商人购买。{zone:1438}的夜枭多数时候会掉{item:6889}，{zone:1439}的枭兽也会掉。渔夫可以改用鲁瑟兰水域的{item:6290}（配方40铜）来烹饪，而{area:186}的{npc:6286}会用{item:5472}换“卡多雷的食谱”（需要七条蛛网蜘蛛的小蜘蛛腿），10到50点均为橙色。",
	["{item:6888}: ingredients"] = "{item:6888}：材料",
	["{item:6888}: shopping"] = "{item:6888}：采购",
	["{item:6890} (50-80)"] = "{item:6890}（50-80）",
	["{item:6890} is orange from 50 (yellow at 80, green at 100, grey at 120): about 30 crafts to 80. Cook at any fire: a town hearth or your own {object:29784}. {item:6892} costs 2s 50c at its vendor; the arrow picks the nearest one of your faction. Black bears roam the hills of {zone:1432}."] = "{item:6890}从50起为橙色（80黄、100绿、120灰）：做到80约需30次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:6892}在商人处售价2银50铜；箭头会指向本阵营最近的一位。黑熊在{zone:1432}的丘陵游荡。",
	["{item:6890}: ingredients"] = "{item:6890}：材料",
	["{item:6890}: shopping"] = "{item:6890}：采购",
	["{item:7974} comes from Big-mouth Clams: open each one, every clam holds one. The Muckshell crabs on the {zone:1445} coast south-west of Theramore drop a clam about seven kills in ten, so ten clams take about fifteen kills, on your way to {zone:1446}. The Steeljaw Snappers on {zone:1446}'s east coast drop them about one kill in three."] = "{item:7974}来自大嘴蛤蜊：每个都要打开，每只蛤蜊里都有一个。塞拉摩西南{zone:1445}海岸的泥壳蟹约每十次击杀掉落七次蛤蜊，所以十个蛤蜊约需十五次击杀，正好在去{zone:1446}的路上。{zone:1446}东海岸的钢颚钳嘴龟约每三次击杀掉一次。",
	["{npc:1126} (36%), {npc:1125} (34%) in {zone:1426}, or wherever the arrow points"] = "{zone:1426}的{npc:1126}（36%）、{npc:1125}（34%），或箭头指向的任何地方",
