	["{npc:3812} (42%), {npc:3814} (42%), {npc:3944} (42%) in {zone:1439}, or wherever the arrow points; open each {item:5523} for its {item:5503}"] = "{zone:1439}的{npc:3812}（42%）、{npc:3814}（42%）、{npc:3944}（42%），或箭头指向的任何地方；打开每个{item:5523}获取其中的{item:5503}",
	["{npc:3814} (42%), {npc:3812} (40%) in {zone:1439}, or wherever the arrow points"] = "{zone:1439}的{npc:3814}（42%）、{npc:3812}（40%），或箭头指向的任何地方",
	["{npc:830} (43%) in {zone:1436}, or wherever the arrow points"] = "{zone:1436}的{npc:830}（43%），或箭头指向的任何地方",
	["{npc:834} (54%), {npc:833} (51%) in {zone:1436}, or wherever the arrow points"] = "{zone:1436}的{npc:834}（54%）、{npc:833}（51%），或箭头指向的任何地方",
	["{quest:6610} asks for 12 Giant Eggs, 10 {item:7974} and 20 {item:8932}: bring all three before you go to {zone:1446}, so you make the trip once. Giant Eggs drop from the owlbeasts of {zone:1425}: {npc:2929} (54%). {item:12218} takes about 120 more after Artisan: farm them now too if you like."] = "{quest:6610}需要12枚巨型蛋、10个{item:7974}和20个{item:8932}：去{zone:1446}之前把三样都备齐，这样只需跑一趟。巨型蛋由{zone:1425}的枭兽掉落：{npc:2929}（54%）。大师级之后{item:12218}还需要约120个，愿意的话也可以现在一起刷。",
	["{skill:185} 1-300"] = "{skill:185} 1-300",
	["{spell:2538} (1-50)"] = "{spell:2538}（1-50）",
	["{spell:2538} is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own {object:29784}."] = "{spell:2538}从1起为橙色（45黄、65绿、85灰）：做到50约需50次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。",
	["{spell:2538} is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own {object:29784}. The Vuldren of Zephras Isle drop {item:2672}."] = "{spell:2538}从1起为橙色（45黄、65绿、85灰）：做到50约需50次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。泽弗拉斯岛的鹫龙会掉落{item:2672}。",
	["{spell:2540} (1-50)"] = "{spell:2540}（1-50）",
	["{spell:2540} is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own {object:29784}."] = "{spell:2540}从1起为橙色（45黄、65绿、85灰）：做到50约需50次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。",
	["{spell:2541} (50-90)"] = "{spell:2541}（50-90）",
	["{spell:2541} is orange from 50 (yellow at 90, green at 110, grey at 130): about 40 crafts to 90. Cook at any fire: a town hearth or your own {object:29784}. Any {skill:185} trainer teaches it from skill 50 for 1s. Coyotes roam the middle of {zone:1436}; {npc:235} on the farm north of {area:108} also gives {item:733} and {item:724} quests that use what you loot here."] = "{spell:2541}从50起为橙色（90黄、110绿、130灰）：做到90约需40次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。任何{skill:185}训练师都会从技能50起以1银教授它。郊狼在{zone:1436}中部游荡；{area:108}以北农场的{npc:235}还会给需要此处战利品的{item:733}和{item:724}任务。",
	["{spell:2541}: ingredients"] = "{spell:2541}：材料",
	["{spell:2544} (90-130)"] = "{spell:2544}（90-130）",
	["{spell:2544} is orange from 90 (yellow at 115, green at 135, grey at 155): about 44 crafts to 130. Cook at any fire: a town hearth or your own {object:29784}. Any {skill:185} trainer teaches it from skill 75 for 2s. Crawlers line the whole {zone:1436} coast. Cook it to 130, where {spell:3376} takes over."] = "{spell:2544}从90起为橙色（115黄、135绿、155灰）：做到130约需44次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。任何{skill:185}训练师都会从技能75起以2银教授它。爬行者遍布{zone:1436}整条海岸。做到130，之后改用{spell:3376}。",
	["{spell:2544} is orange from 90 (yellow at 115, green at 135, grey at 155): about 44 crafts to 130. Cook at any fire: a town hearth or your own {object:29784}. Any {skill:185} trainer teaches it from skill 75 for 2s. Crawlers line the whole {zone:1439} coast. Cook it to 130, where {spell:3376} takes over."] = "{spell:2544}从90起为橙色（115黄、135绿、155灰）：做到130约需44次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。任何{skill:185}训练师都会从技能75起以2银教授它。爬行者遍布{zone:1439}整条海岸。做到130，之后改用{spell:3376}。",
	["{spell:2544}: ingredients"] = "{spell:2544}：材料",
	["{spell:2544}: shopping"] = "{spell:2544}：采购",
	["{spell:2546} (80-130)"] = "{spell:2546}（80-130）",
	["{spell:2546} is orange from 80 (yellow at 120, green at 140, grey at 160): about 52 crafts to 130. Cook at any fire: a town hearth or your own {object:29784}. Any {skill:185} trainer teaches it from skill 80 for 1s 50c. Mountain boars roam all of {zone:1432}. Cook it to 130, where {spell:3376} takes over."] = "{spell:2546}从80起为橙色（120黄、140绿、160灰）：做到130约需52次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。任何{skill:185}训练师都会从技能80起以1银50铜教授它。山地野猪遍布{zone:1432}。做到130，之后改用{spell:3376}。",
	["{spell:2546}: ingredients"] = "{spell:2546}：材料",
	["{spell:2546}: shopping"] = "{spell:2546}：采购",
	["{spell:3376} (130-175)"] = "{spell:3376}（130-175）",
	["{spell:3376} is orange from 130 (yellow at 170, green at 190, grey at 210): about 46 crafts to 175. Cook at any fire: a town hearth or your own {object:29784}. {item:3682} costs 16s at its vendor; the arrow picks the nearest one of your faction. The raptors of the {zone:1437} drop a {item:3685} about two kills in three. {npc:340} in {zone:1453} sells the recipe."] = "{spell:3376}从130起为橙色（170黄、190绿、210灰）：做到175约需46次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:3682}在商人处售价16银；箭头会指向本阵营最近的一位。{zone:1437}的迅猛龙约每三次击杀掉一次{item:3685}。{zone:1453}的{npc:340}出售配方。",
	["{spell:3398} (130-175)"] = "{spell:3398}（130-175）",
	["{spell:3398} is orange from 130 (yellow at 175, green at 195, grey at 215): about 45 crafts to 175. Cook at any fire: a town hearth or your own {object:29784}. {item:3735} costs 18s at its vendor; the arrow picks the nearest one of your faction. The Feral and Hulking Mountain Lions of Hillsbrad Foothills drop {item:3731} more often than the Starving ones."] = "{spell:3398}从130起为橙色（175黄、195绿、215灰）：做到175约需45次。在任何火堆旁烹饪：城镇炉火或你自己的{object:29784}。{item:3735}在商人处售价18银；箭头会指向本阵营最近的一位。希尔斯布莱德丘陵的凶猛山地狮和魁梧山地狮比饥饿山地狮更常掉落{item:3731}。",
}

G["forever/professions/herbalism"] = {
	["Any {skill:182} trainer of your faction teaches Apprentice {skill:182} at any level (10c), and so does the Junior Herbalism Trainer in each starting area; the arrow picks the nearest. Turn on {spell:2383} (spellbook, General tab) so herbs show on the minimap. Forever's starting areas also have {object:656160} and {object:656161} (skill 1). The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) offers {item:247841} as a reward: reading it gives 2 skill, up to 15. Trade goods vendors sell the {item:277113}, a four-slot bag for herbs (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:182}: hand it in to the herbalism trainer it names once you reach skill 20, for the {spell:1229705} recipe."] = "任何本阵营的{skill:182}训练师都能在任意等级教学徒级{skill:182}（10铜），每个起始区域的初级草药训练师也一样；箭头会指向最近的一位。打开{spell:2383}（法术书，通用页签），草药就会显示在小地图上。Forever的起始区域还有{object:656160}和{object:656161}（技能1起可采）。每个起始区域的第一小时任务（捣乱的啮齿动物、寒脊山谷送信、林地守护者、加尔加的{item:11584}、简单的任务、玛拉的遗愿）会以{item:247841}作为奖励：阅读它可得2点技能，最多到15。贸易品商人出售{item:277113}，一个装药草的四格包（25铜）。如果你为了《野外生存》在起始区域的篝火旁坐过，那里的露营指南还会提供《露营入门：{skill:182}》：技能达到20后，把它交给任务指定的草药训练师，换取{spell:1229705}配方。",
	["Artisan {skill:182} raises the cap to 300; it needs skill 200 and no character level, and costs 5g: train it as soon as you reach 200. The arrow picks the nearest {skill:182} trainer of your faction."] = "大师级{skill:182}把上限提高到300；需要技能200，不限角色等级，花费5金：一到200就立刻学习。箭头会指向本阵营最近的{skill:182}训练师。",
	["Expert {skill:182} raises the cap to 225; it needs skill 125 and no character level, and costs 50s: train it as soon as you reach 125. The arrow picks the nearest {skill:182} trainer of your faction."] = "高级{skill:182}把上限提高到225；需要技能125，不限角色等级，花费50银：一到125就立刻学习。箭头会指向本阵营最近的{skill:182}训练师。",
	["Journeyman {skill:182} raises the cap to 150; it needs skill 50 and no character level, and costs 5s: train it as soon as you reach 50. The arrow picks the nearest {skill:182} trainer of your faction. {spell:1229705}, Forever's camping item for {skill:182}, is taught from skill 20 (1s, or free from Camping 101: {skill:182}): a {item:2447} and a {item:765} each, it gives points until 25; placed beside a campfire it gives everyone at the camp a buff for an hour."] = "中级{skill:182}把上限提高到150；需要技能50，不限角色等级，花费5银：一到50就立刻学习。箭头会指向本阵营最近的{skill:182}训练师。{spell:1229705}是Forever的{skill:182}露营物品，技能20起可学（1银，或从《露营入门：{skill:182}》免费获得）：每次用一个{item:2447}和一个{item:765}，能给技能点直到25；放在营火旁能为一小时内的所有营地成员提供增益。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "路过时采下每一个{item:2447}（1点，橙色）、{item:765}（1点，橙色）、{item:2449}（15点起），并绕着路标循环，直到{skill:182} 50。区域等级1-10。这49点大约需要60株草药。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-15. Expect about 60 herbs for these 49 points."] = "路过时采下每一个{item:2447}（1点，橙色）、{item:765}（1点，橙色）、{item:2449}（15点起），并绕着路标循环，直到{skill:182} 50。区域等级1-15。这49点大约需要60株草药。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange), {object:656160} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "路过时采下每一个{item:2447}（1点，橙色）、{item:765}（1点，橙色）、{object:656161}（1点，橙色）、{object:656160}（1点，橙色）、{item:2449}（15点起），并绕着路标循环，直到{skill:182} 50。区域等级1-10。这49点大约需要60株草药。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange, rare), {object:656160} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "路过时采下每一个{item:2447}（1点，橙色）、{item:765}（1点，橙色）、{object:656161}（1点，橙色，稀有）、{object:656160}（1点，橙色）、{item:2449}（15点起），并绕着路标循环，直到{skill:182} 50。区域等级1-10。这49点大约需要60株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "路过时采下每一个{item:2447}（1点，黄色）、{item:765}（1点，黄色）、{item:2449}（15点，黄色）、{item:785}（50点，橙色）、{item:2450}（70点起），并绕着路标循环，直到{skill:182} 100。{item:785}和{item:2450}有时还会额外给一个{item:2452}。区域等级10-20。这50点大约需要140株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. A quest here needs {skill:182}: Root Samples (level 16, {npc:3446}). Zone level 10-25. Expect about 110 herbs for these 50 points."] = "路过时采下每一个{item:2447}（1点，黄色）、{item:765}（1点，黄色）、{item:2449}（15点，黄色）、{item:785}（50点，橙色）、{item:2450}（70点起）、{item:3820}（85点起），并绕着路标循环，直到{skill:182} 100。{item:785}和{item:2450}有时还会额外给一个{item:2452}。{item:3820}生长在岸边水下：注意呼吸。这里的某个任务需要{skill:182}：根茎样本（16级，{npc:3446}）。区域等级10-25。这50点大约需要110株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 10-20. Expect about 130 herbs for these 50 points."] = "路过时采下每一个{item:2447}（1点，黄色）、{item:765}（1点，黄色）、{item:2449}（15点，黄色）、{item:785}（50点，橙色）、{item:2450}（70点起）、{item:3820}（85点起），并绕着路标循环，直到{skill:182} 100。{item:785}和{item:2450}有时还会额外给一个{item:2452}。{item:3820}生长在岸边水下：注意呼吸。区域等级10-20。这50点大约需要130株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "路过时采下每一个{item:2447}（1点，黄色）、{item:765}（1点，黄色）、{item:2449}（15点，黄色）、{item:785}（50点，橙色）、{item:2450}（70点起）、{item:3820}（85点起），并绕着路标循环，直到{skill:182} 100。{item:785}和{item:2450}有时还会额外给一个{item:2452}。{item:3820}生长在岸边水下：注意呼吸。区域等级10-20。这50点大约需要140株草药。",
	["Pick every {item:2449} (15, green), {item:785} (50, green), {item:2450} (70, yellow), {item:2453} (100, orange) you pass and circle the waypoints until {skill:182} 125. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 15-25. Expect about 60 herbs for these 25 points."] = "路过时采下每一个{item:2449}（15点，绿色）、{item:785}（50点，绿色）、{item:2450}（70点，黄色）、{item:2453}（100点，橙色），并绕着路标循环，直到{skill:182} 125。{item:785}和{item:2450}有时还会额外给一个{item:2452}。区域等级15-25。这25点大约需要60株草药。",
	["Pick every {item:2450} (70, green, rare), {item:3820} (85, green), {item:2453} (100, green, rare), {object:1623} (115, yellow, rare), {item:3356} (125, yellow), {item:3357} (150, orange), {item:3818} (160, orange), {item:3821} (from 170) you pass and circle the waypoints until {skill:182} 185. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 35-45. Expect about 40 herbs for these 25 points."] = "路过时采下每一个{item:2450}（70点，绿色，稀有）、{item:3820}（85点，绿色）、{item:2453}（100点，绿色，稀有）、{object:1623}（115点，黄色，稀有）、{item:3356}（125点，黄色）、{item:3357}（150点，橙色）、{item:3818}（160点，橙色）、{item:3821}（170点起），并绕着路标循环，直到{skill:182} 185。{item:785}和{item:2450}有时还会额外给一个{item:2452}。{item:3820}生长在岸边水下：注意呼吸。区域等级35-45。这25点大约需要40株草药。",
