}

G["forever/class/druid/cat-form"] = {
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}降到{area:2361}的{npc:11802}身旁（泽弗拉斯岛上没人接天裔任务），然后从{npc:11798}处飞往{area:1638}。{npc:11802}站在他所在建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}降到{area:2361}的{npc:11802}身旁（泽弗拉斯岛上没人接天裔任务），然后乘{npc:11800}的航班前往{area:702}：她站在{area:2361}中央，专门载德鲁伊去那里，无需飞行点。{npc:11802}站在他所在建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。{npc:11802}站在{area:2361}他所在建筑的楼上：从里面上楼，箭头分不清楼层。",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "施放{spell:18960}。{npc:11802}站在{area:2361}他所在建筑的楼上：从里面上楼，箭头分不清楼层。如果还没有那里的飞行点，顺便开了。",
	["Druid"] = "德鲁伊",
	["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "乘传送门上楼到{npc:4217}处，他在{area:1658}的楼上：他教你{spell:768}。",
	["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{area:1639}的{npc:3033}教你{spell:768}。",
	["{npc:3033} stands in the druids' hut on {area:1639}. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:3033}站在{area:1639}的德鲁伊小屋。还没学水栖形态？顺便从他那里接“汲取教训”：它也通向{npc:11802}，其中的“湖中试炼”（水栖形态攻略）就在同一个{area:493}内。",
	["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:4217}站在{area:1658}。天裔离{zone:1457}很远：施放{spell:18960}，在{area:2361}中央乘{npc:11800}的航班（她专门载德鲁伊去{area:702}，无需飞行点），再乘传送门上楼。还没学水栖形态？也从他那里接“汲取教训”：它同样通向{npc:11802}，其“湖中试炼”（水栖形态攻略）就在同一个{area:493}。",
	["{quest:98342} (Tauren) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98342}（牛头人）在{area:493}南部桥上方的小山上；{npc:272054}（天裔）站在双桥过去的高地上，位于{area:2361}西南：爬上去找它。圣物在湖东的{area:2363}：解除形态，点击巢穴入口处的雕像，可获得短暂潜行（五分钟），然后深入洞穴并越过桥。狂怒的灵魂守卫着圣物，见到什么就攻击什么：保持雕像给予的潜行，一直移动。每件圣物都是壁龛里猫雕像旁的小球：毒牙和利爪各有一处，无声之影有两处，也正是玩家常蹲守的那处。别人正在拾取时，圣物会显示为不可用：稍等片刻再试。潜行没了？走回入口的雕像再拿一次。",
	["{quest:98394} (Night Elves) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98394}（暗夜精灵）在{area:493}南部桥上方的小山上；{npc:272054}（天裔）站在双桥过去的高地上，位于{area:2361}西南：爬上去找它。圣物在湖东的{area:2363}：解除形态，点击巢穴入口处的雕像，可获得短暂潜行（五分钟），然后深入洞穴并越过桥。狂怒的灵魂守卫着圣物，见到什么就攻击什么：保持雕像给予的潜行，一直移动。每件圣物都是壁龛里猫雕像旁的小球：毒牙和利爪各有一处，无声之影有两处，也正是玩家常蹲守的那处。别人正在拾取时，圣物会显示为不可用：稍等片刻再试。潜行没了？走回入口的雕像再拿一次。",
}

G["forever/class/warlock/orb-of-orahil"] = {
	["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "带着净化过的宝珠回到{area:392}上方塔楼里的{npc:6266}处。在地狱犬路线中，接下她最后一个任务，在她完成{item:15108}时守在她身旁（不要攻击她：任务记录称之为击杀），然后再次与她交谈，选择副手宝珠或法杖。",
	["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "先带着灵魂和宝石回到{area:392}上方塔楼里的{npc:6266}处：她的宝珠由此而来。",
	["Demon of the Orb"] = "宝珠中的恶魔",
	["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "在地狱火路线中，接下她最后一个任务，在{npc:6266}完成{item:15107}时守在她身旁，然后再次与她交谈，选择副手宝珠或法杖。",
	["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "只选一名侍从：你只能接其中一人的任务。{npc:6254}的地狱犬路线最终给宝珠或{item:15106}，即暗影版本；{npc:6252}的地狱火路线最终给宝珠或{item:15105}，火系版本物品大同小异。多数术士偏向暗影，但先对比这四件物品的提示信息。攻略会跟随你选择的那条。保留红宝石或绿宝石：它们会归还。",
	["Wait beside {npc:6266} while she makes the orb"] = "在{npc:6266}制作宝珠时守在她身旁",
	["Warlock"] = "术士",
	["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602}占据{zone:1443}中南部，在{area:2408}以东。燃烧之刃召唤者（38到39级，带小鬼的术士）每次都带着{item:7291}。要取灵魂，先用持续伤害把你的恶魔打到低血量，然后对它引导红宝石或绿宝石，并在它死亡期间持续引导，方式类似{spell:1120}：宝石本身不造成伤害。红宝石对燃烧之刃的地狱犬有效：北部的两只法力吞噬者（37到38级），以及更南边的法师猎手（38级）和灵能猎手（39级）。绿宝石对次级地狱火有效（36到37级，共十六只，抗火）。",
	["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}，来自{npc:4678}、{npc:4681}或{npc:4685}",
	["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266}和她的两名侍从站在{area:392}上方山丘上{npc:6251}的塔里。",
	["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Before you accept Cleansing, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 35-38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546}住在{zone:1445}中部的农场，位于从{zone:1413}来的道路以南、塞拉摩西南；农场旁有位灵魂医者。死沼——一头45级鳄鱼——就在东北边的溪流间巡逻。接“净化”之前，先清掉她围栏周围的蜘蛛和鳄鱼。接任务后开始3分钟计时：她会走向围栏，把{npc:6549}放出来。它是40级精英：建议组队；40级左右的术士可以用恐惧或{spell:710}加持续伤害单挑，35到38级的则带个朋友。击杀后计时仍在走，所以立刻交任务。时间耗尽就放弃任务，再从{npc:6546}处接一次。",
}

G["forever/collectibles/pets/condor-hatchling"] = {
	["{npc:14268} is a rare level 15-16 condor in south-eastern {zone:1432}. He appears at one of four spots, hours after he last died; the arrow takes you round them. He drops the {item:282637} only about once in 500 kills, so this is a pet for players who pass through {zone:1432} often: check his spots each time, and kill him whenever you see him."] = "{npc:14268}是{zone:1432}东南部的一只15到16级稀有秃鹫。他会在上次死亡数小时后出现在四个位置之一；箭头会带你依次转一圈。他掉落{item:282637}的概率约为每500次击杀一次，所以这是给常经过{zone:1432}的玩家的宠物：每次都去检查他的刷新点，见到就杀。",
}

G["forever/collectibles/pets/smolderweb-carrier"] = {
	["Lower {area:1583} is a group of five, level 55-60, inside {area:254}. The Spire Spider Eggs lie around {npc:10596}'s nest in the Skitterweb Tunnels, the spider halls: click them until you have 15 (each gives one to three). Hard-hitting spiderlings can hatch as you loot. By player reports the eggs cannot be looted in a raid group, so keep the party at five or fewer."] = "下层{area:1583}是五人副本，55到60级，位于{area:254}内。尖塔蜘蛛蛋散落在蛛网隧道——即蜘蛛大厅——中{npc:10596}的巢穴周围：点击它们直到凑够15个（每个给一到三个）。拾取时可能孵出攻击凶猛的蜘蛛幼体。据玩家反映，团队状态下无法拾取这些蛋，所以队伍保持在五人以内。",
	["{npc:10260} stands inside the cave at {area:251}, the camp in northern {zone:1428} east of {area:254}. He also gives {npc:10260}'s Exotic Pets (the {item:12264}): take both, they are done in the same run."] = "{npc:10260}站在{area:251}的洞穴里，那是{zone:1428}北部、{area:254}以东的营地。他还会给{npc:10260}的异域宠物任务（需{item:12264}）：两个都接，一趟就能做完。",
}

G["forever/exploration/eastern-kingdoms-1-30"] = {
	["Fly from {area:144} to {zone:1453} if you have its flight path; otherwise ride back to {zone:1455} and take the {area:2257}. Walk west out of {zone:1429} past the {area:120} into {zone:1436}."] = "若已开通飞行点，从{area:144}飞往{zone:1453}；否则骑回{zone:1455}，乘{area:2257}。从{zone:1429}向西步行，经过{area:120}进入{zone:1436}。",
	["Fly from {area:42} to {area:144} in {zone:1432} and ride north through the {area:836} pass into the {zone:1437}."] = "从{area:42}飞往{zone:1432}的{area:144}，再向北骑，穿过{area:836}山口进入{zone:1437}。",
	["From {area:1002} take the road south into {zone:1431}; {area:42} is east along its main road. Most of Duskwood is level 24-30: come with Redridge behind you."] = "从{area:1002}沿路向南进入{zone:1431}；{area:42}就在主路东侧。暮色森林大部分是24到30级：先做完赤脊山再来。",
	["From {area:925} take the {area:807} tunnel west into {zone:1426}. {area:131} and {zone:1455}'s gates are Alliance ground."] = "从{area:925}走{area:807}隧道向西进入{zone:1426}。{area:131}和{zone:1455}的大门一带是联盟领地。",
	["Go back east through {zone:1429}: the road past the {area:88} enters Redridge at {area:1002}, where the roads from {zone:1429} and {zone:1431} meet."] = "向东穿过{zone:1429}返回：经过{area:88}的道路在{area:1002}进入赤脊山，来自{zone:1429}和{zone:1431}的道路在那儿交汇。",
	["Leave {zone:1426} east through the South Gate tunnel; it opens into {zone:1432} by the dwarf king statues of the {area:924}."] = "从南门隧道向东离开{zone:1426}；出来后就是{zone:1432}，位于{area:924}的矮人国王雕像旁。",
	["Take the boat from {area:150} to {area:271}."] = "从{area:150}乘船到{area:271}。",
