G["forever/miscellaneous/cozy-sleeping-bag"] = {
	["North of Honor's Stand"] = "荣誉岗哨以北",
	["The chain opens at level 14. A burned-out campfire in the southern {zone:1413}, with a nailed plank beside it."] = "任务链在14级开放。{zone:1413}南部有一处烧尽的营火，旁边钉着一块木板。",
	["The chain opens at level 14. A burned-out campfire in western {zone:1436}, with a nailed plank beside it."] = "任务链在14级开放。{zone:1436}西部有一处烧尽的营火，旁边钉着一块木板。",
	["The next hideout is a small camp in the hills north-west of {area:460}, in the middle of the {zone:1442}. Leave the road where a path climbs west into the hills and follow it to the camp; the {object:424005} lies on a crate beside its tent."] = "下一个藏身处是{zone:1442}中部{area:460}西北山丘中的小营地。在有小径向西爬上山丘的地方离开道路，沿小径走到营地；{object:424005}就在帐篷旁的木箱上。",
	["The road west runs through {area:1702}, a Horde post; this way goes round it."] = "向西的道路穿过{area:1702}——一个部落据点；这条路会绕开它。",
}

